/* 构建产物，不要手改。源文件在 stmg/*.py */
window.STMG_ENGINE_SRC={"/stmg_root/stmg/__init__.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 引擎（网页版子集：解析 + 运行 + 网页桥 + 制作器工具，不含界面）。\"\"\"\n\nfrom .errors import STMFatal, Issue, level_name        # noqa: F401\nfrom .parser import Script, parse_file, parse_text     # noqa: F401\nfrom .runtime import Runtime                           # noqa: F401\n\n__version__ = \"1.0.0\"\n","/stmg_root/stmg/errors.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 的错误体系。\n\n设计稿定的五级命名原样保留：\n\n    A error        1 个\n    An error       2 ~ 39 个\n    Many error     40 ~ 49 个\n    Lot of error   50 ~ 99 个\n    Bro....        100 个以上\n\"\"\"\n\nimport os\nimport traceback\n\n\ndef level_name(n):\n    \"\"\"按错误数量 n 返回设计稿定的「严重程度称呼」（见文件头）。\n\n    这些阈值（1 / 40 / 50 / 100）是设计稿钦定的等级分界线，\n    纯粹为了给用户一个「哎呀情况有多糟」的直观说法，不影响任何逻辑。\n    0 个错误返回 None —— 调用方据此判断要不要显示这一行。\n    \"\"\"\n    if n <= 0:\n        return None\n    if n == 1:\n        return \"A error\"\n    if n < 40:\n        return \"An error\"\n    if n < 50:\n        return \"Many error\"\n    if n < 100:\n        return \"Lot of error\"\n    return \"Bro....\"\n\n\nclass Issue(object):\n    \"\"\"一条语法 / 运行时问题。level 取 'error' 或 'warn'。\"\"\"\n\n    def __init__(self, line, message, hint=\"\", level=\"error\"):\n        self.line = line\n        self.message = message\n        self.hint = hint\n        self.level = level\n\n    def __str__(self):\n        pos = \"行 %d\" % self.line if self.line else \"全局\"\n        s = \"[%s] %s\" % (pos, self.message)\n        if self.hint:\n            s += \"  -> \" + self.hint\n        return s\n\n\nclass STMFatal(Exception):\n    \"\"\"跑不下去了，必须停机。\"\"\"\n\n    def __init__(self, message, line=None):\n        Exception.__init__(self, message)\n        self.message = message\n        self.line = line\n\n    def __str__(self):\n        if self.line:\n            return \"行 %s: %s\" % (self.line, self.message)\n        return self.message\n\n\nclass ErrorBag(object):\n    \"\"\"收集一次运行里的所有问题。\"\"\"\n\n    def __init__(self, path=\"\"):\n        self.path = path\n        self.issues = []\n\n    def add(self, line, message, hint=\"\", level=\"error\"):\n        self.issues.append(Issue(line, message, hint, level))\n\n    def warn(self, line, message, hint=\"\"):\n        self.issues.append(Issue(line, message, hint, \"warn\"))\n\n    def extend(self, issues):\n        self.issues.extend(issues)\n\n    @property\n    def errors(self):\n        return [i for i in self.issues if i.level == \"error\"]\n\n    @property\n    def warns(self):\n        return [i for i in self.issues if i.level == \"warn\"]\n\n    def __len__(self):\n        return len(self.issues)\n\n    def report(self, max_lines=40):\n        \"\"\"把收集到的问题拼成一段人看的报告文本（尽量说人话，不堆术语）。\n\n        max_lines 限制一次最多显示多少条，超出的用「还有 N 条没显示」带过，\n        免得一个满是错的剧本把报告刷到没边。末尾若统计出错误数，会再补一句\n        严重程度称呼（level_name）和一句「修掉带『错误』的就能正常启动」的引导。\n        \"\"\"\n        if not self.issues:\n            return \"没有发现问题，剧本看起来没问题。\"\n        out = []\n        if self.path:\n            out.append(\"文件: %s\" % self.path)\n        for i in self.issues[:max_lines]:\n            tag = \"错误\" if i.level == \"error\" else \"提示\"\n            out.append(\" %s  %s\" % (tag, i))\n        if len(self.issues) > max_lines:\n            out.append(\" ... 还有 %d 条没显示\" % (len(self.issues) - max_lines))\n        name = level_name(len(self.errors))\n        if name:\n            out.append(\"\")\n            out.append(\"以上一共发现 %d 个错误（%s），修掉带「错误」的就能正常启动\"\n                       % (len(self.errors), name))\n        return \"\\n\".join(out)\n\n\ndef format_exception(exc):\n    \"\"\"给开发版报错界面用的「短回溯」——只保留和本项目有关的栈帧。\n\n    正常报错会带出一长串 Python 标准库、pygame、第三方包的栈，对玩家来说\n    全是噪声。这里把路径里含 \"site-packages\" 的帧（即第三方库内部）整段剔除，\n    只留用户剧本 / 引擎源码这一层，开发版界面一眼就能定位到坏在哪一行。\n    \"\"\"\n    lines = traceback.format_exception(type(exc), exc, exc.__traceback__)\n    keep = []\n    for ln in lines:\n        if \"site-packages\" in ln:\n            continue                    # 第三方库内部栈：开发界面不关心\n        keep.append(ln.rstrip())\n    return os.linesep.join(keep)\n","/stmg_root/stmg/markdown.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 的 Markdown 内联渲染模块。\n\n设计稿里只写了「\"**hello**\"加粗」+「就是把 md 的特性加入到制作 galgame 中」，\n所以这里先支持最常用的一小撮，够用且好扩展：\n\n    **粗体**   *斜体*   ~~删除线~~   `等宽`\n    [color=#ff5555]红色[/color]\n    [size=20]字号[/size]\n    {ruby:汉字|かんじ}          —— 注音（给角色名/生僻字用）\n\n输出「run 列表」，交给 gui.py 决定怎么画。\n\"\"\"\n\nimport re\n\n# 内联标记的正则。用命名分组（?P<xxx>）把每种标记分开，下面 render() 里\n# 按「哪个分组捕获到了」判断这是哪种标记——排在前面的优先匹配。\n#   color   [color=#ff5555]红[/color]   改颜色（#rgb/#rrggbb 或英文色名）\n#   size    [size=20]大[/size]          改字号\n#   ruby    注音：{ruby:汉字|かんじ}    生僻字/角色名的假名注音（兼容「注音:」写法）\n#   bold    **粗**                      粗体\n#   strike  ~~删~~                      删除线\n#   code    `等宽`                      等宽字体（代码感）\n#   italic  *斜*                        斜体（左右不能是 *，避免和 ** 粗体打架）\n# re.S 让 . 也能匹配换行，标记可跨行。\nTOKEN_RE = re.compile(\n    r\"\\[color=(?P<color>#[0-9a-fA-F]{3,8}|[A-Za-z]+)\\](?P<colortext>.*?)\\[/color\\]\"\n    r\"|\\[size=(?P<size>\\d+)\\](?P<sizetext>.*?)\\[/size\\]\"\n    r\"|\\{(?:ruby|注音):(?P<rbase>[^|]+)\\|(?P<rtext>[^}]+)\\}\"\n    r\"|\\*\\*(?P<bold>.+?)\\*\\*\"\n    r\"|~~(?P<strike>.+?)~~\"\n    r\"|`(?P<code>[^`]+)`\"\n    r\"|(?<!\\*)\\*(?P<italic>[^*]+)\\*(?!\\*)\",\n    re.S,\n)\n\n\ndef render(text):\n    \"\"\"把一段带 md 标记的文本切成 run 列表。\n\n    每个 run（一段「同款样式」的文字）长这样：\n        {\"t\": 文本, \"bold\": bool, \"italic\": bool,\n         \"strike\": bool, \"code\": bool, \"color\": None|str, \"size\": None|int}\n    同一次出现的样式叠加（比如 **红字** 同时 bold=True 且 color 有值），\n    怎么画交给 gui.py——这里只负责「识别和切段」，不碰绘制。\n\n    做法：pos 记下「上次处理到的位置」，每匹配到一个标记，先把 pos 到标记\n    开头之间的纯文本塞一段，再处理标记本身，最后把 pos 推到标记末尾；\n    循环结束若还有剩，把尾巴当纯文本收掉。\n    \"\"\"\n    # 一段文本的「默认样式模板」，每个 run 都从它拷贝再改个别字段\n    base = {\"t\": \"\", \"bold\": False, \"italic\": False,\n            \"strike\": False, \"code\": False, \"color\": None, \"size\": None}\n    runs, pos = [], 0\n    for m in TOKEN_RE.finditer(text):\n        # 标记前面的纯文本（没有标记的部分），单独成一段\n        if m.start() > pos:\n            runs.append(dict(base, t=text[pos:m.start()]))\n        pos = m.end()\n        # 按「哪个命名分组命中」分流；同时命中也只走第一个非 None 的分支\n        if m.group(\"colortext\") is not None:\n            # 改颜色：color 记下色值，文字本身照原样\n            runs.append(dict(base, t=m.group(\"colortext\"), color=m.group(\"color\")))\n        elif m.group(\"sizetext\") is not None:\n            # 改字号：size 捕获的是字符串，转成 int 用\n            runs.append(dict(base, t=m.group(\"sizetext\"), size=int(m.group(\"size\"))))\n        elif m.group(\"rbase\") is not None:\n            # 注音：正文用汉字，后面跟一段灰色小号假名（用括号包起来）\n            runs.append(dict(base, t=m.group(\"rbase\")))\n            runs.append(dict(base, t=\"(%s)\" % m.group(\"rtext\"), size=10, color=\"#888888\"))\n        elif m.group(\"bold\") is not None:\n            runs.append(dict(base, t=m.group(\"bold\"), bold=True))\n        elif m.group(\"strike\") is not None:\n            runs.append(dict(base, t=m.group(\"strike\"), strike=True))\n        elif m.group(\"code\") is not None:\n            runs.append(dict(base, t=m.group(\"code\"), code=True))\n        elif m.group(\"italic\") is not None:\n            runs.append(dict(base, t=m.group(\"italic\"), italic=True))\n    # 收尾：最后一个标记之后如果还有纯文本，补一段\n    if pos < len(text):\n        runs.append(dict(base, t=text[pos:]))\n    # 丢掉空段（两个相邻标记之间什么都没写），避免 gui 画空 run\n    return [r for r in runs if r[\"t\"] != \"\"]\n\n\ndef plain(text):\n    \"\"\"去掉所有 md 标记，得到纯文本（给打字机效果 / 历史记录用）。\"\"\"\n    return \"\".join(r[\"t\"] for r in render(text))\n\n\ndef strip_quotes(text):\n    \"\"\"剥掉文本首尾的英文双引号（剧本里字符串字面量常写成 \"xxx\"）。\n\n    只在外层成对是 \" 时才剥；只有一个或不是引号则原样返回。\n    \"\"\"\n    t = text.strip()\n    # 至少两个字符、且首末都是 \" 才认为是被引号包住，去掉这两层\n    if len(t) >= 2 and t[0] == '\"' and t[-1] == '\"':\n        return t[1:-1]\n    return t\n","/stmg_root/stmg/parser.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 剧本解析器 —— 把 .stm 剧本解析成语句树（AST）。\n\n语法以 ciallo0721-cmd 的《Super Text Markdown Galgame language》设计稿为准。\n设计稿里没写死、但解析必须拍板的地方，README 的「设计稿之外的补充约定」一节列了。\n\"\"\"\n\nimport os\nimport re\n\nfrom .errors import Issue, level_name  # noqa: F401  (level_name 供外部复用)\nfrom . import avg as avgmod   # AVG 绘图：SET 块里的指令编译用它（avg.py 不依赖本包其他模块）\n\nCOMMENT_RE = re.compile(r\"<--.*?-->\", re.S)\n\n# 设计稿通篇用的是全角引号，直接抄进 .stm 会解析失败，这里自动纠正。\nQUOTE_FIX = {\n    \"\\u201c\": '\"', \"\\u201d\": '\"',\n    \"\\u2018\": \"'\", \"\\u2019\": \"'\",\n}\n\n# 这些词后面跟冒号时不是「标签」，是关键字\nRESERVED = {\"choose\", \"if\", \"else\", \"elif\", \"endif\", \"endchoose\",\n            \"question\", \"set\", \"start\"}\n\nBLOCK_OPEN_RE = re.compile(r\"^<(?P<name>[A-Za-z]*)$\")\nBLOCK_CLOSE_RE = re.compile(r\"^<\/?(?P<name>[A-Za-z]*)>$\")\n\n# < ... python: 代码 ... > —— 内嵌的 Python 代码块。\n# 它和顶层剧情块长得一模一样（都是 < ... >），所以要在 _split_blocks 之前\n# 先整块抠出来，原地留一行占位符，等 _parse_lines 再还原成语句。\n# 占位行必须**保持原有行数**（拿空行补齐），否则后面每一行的行号全会错位。\nPY_BLOCK_OPEN_RE = re.compile(r\"^<\\s*(?:python|py)\\s*:\\s*(.*)$\", re.I)\nPY_BLOCK_KW_RE = re.compile(r\"^(?:python|py)\\s*:\\s*(.*)$\", re.I)\nPY_BLOCK_MARK_RE = re.compile(r\"^__STM_PYBLOCK_(\\d+)__$\")\nPY_DELAY_RE = re.compile(r\"^(?:delay\\s*=\\s*)?(\\d+(?:\\.\\d+)?)\\s*s?$\", re.I)\n\nPY_DELAY_DEFAULT = 3.0     # 代码块里 print 出来的行，默认每行隔 3 秒\nPY_DELAY_MAX = 60.0\n\n# 函数调用 S.play(...) / R.api(...) / S.AVG-button(...)。\n# 方法名里允许连字符（AVG-button 这种）——脚本作者写起来顺口，\n# 解析后统一把 - 换成 _，所以 AVG-button 和 AVG_button 是同一个函数。\nCALL_RE = re.compile(r\"^([A-Za-z_][\\w-]*(?:\\.[A-Za-z_][\\w-]*)*)\\s*\\((.*)\\)\\s*$\", re.S)\n# stm.os(...) —— 受控文件操作。外层只认 stm.os，内层再拆出 操作(path) 和可选的 ,\"旧\"to\"新\"\nSTM_OS_RE = re.compile(r\"^\\s*stm\\.os\\s*\\((.*)\\)\\s*$\", re.I | re.S)\nSTM_OS_INNER_RE = re.compile(\n    r'^\\s*([A-Za-z_]\\w*)\\s*\\(\\s*\"([^\"]*)\"\\s*\\)'\n    r'(?:\\s*,\\s*\"([^\"]*)\"\\s*to\\s*\"([^\"]*)\"\\s*)?$',\n    re.I | re.S)\nLABEL_RE = re.compile(r\"^([A-Za-z_\\u4e00-\\u9fff][\\w\\u4e00-\\u9fff]*)\\s*:\\s*$\")\nIF_RE = re.compile(r\"^If\\s+(.+?)\\s*:\\s*$\", re.I)\nELSE_RE = re.compile(r\"^Else\\s*:\\s*$\", re.I)\nCHOOSE_RE = re.compile(r\"^Choose\\s*:\\s*$\", re.I)\nQUESTION_RE = re.compile(r\"^Question\\s*:\\s*(.*)$\", re.I)\nSET_RE = re.compile(r\"^SET\\s+([\\w.]+)\\s*=\\s*(.*)$\", re.I)\n# SET 名字: （没有 = 号，后面跟一个缩进的绘图指令块）—— AVG 绘图变量。\n# 和 SET x = 1 的赋值是两回事：这种块定义的是一幅可以用\n# S.AVG-button(x, y, \"名字\") 画出来的「海龟绘图」，详见 stmg/avg.py。\nAVG_SET_RE = re.compile(r\"^SET\\s+([A-Za-z_\\u4e00-\\u9fff][\\w\\u4e00-\\u9fff]*)\\s*:\\s*$\", re.I)\nASSIGN_RE = re.compile(r\"^([A-Za-z_][\\w.]*)\\s*=\\s*(.+)$\", re.S)\n# 台词文本支持 \"…\" + 变量 这种拼接（运行时 _say_text 会 eval_expr 求值）。\n# 所以文本部分用 \".* 吃掉到行尾（含 + 号），而不是钉死成单个引号串。\nSAY_RE = re.compile(r'^(?P<who>[^\"\\s][^\"]*?)\\s*[:：]?\\s*(?P<text>\".*)$', re.S)\nBARE_SAY_RE = re.compile(r'^(\".*)$', re.S)\nHEADER_KV_RE = re.compile(r\"^([A-Za-z_]\\w*)\\s*=\\s*(.*)$\")\n# 一整行只由 \"字符串\" 和冒号组成 —— 这才是 Choose 的选项行\nOPTIONS_RE = re.compile(r'^\\s*(?:\"[^\"]*\"\\s*[:：]?\\s*)+\\s*$')\n\n# include 多文件剧本：解析期内联目标文件的正文\nINCLUDE_RE = re.compile(r'^include\\s+\"([^\"]*)\"\\s*$', re.I)\n# 子程序调用：Call \"标签\" 或 Call 标签\nCALLSUB_RE = re.compile(r'^Call\\s+\"([^\"]*)\"\\s*$', re.I)\nCALLSUB_RE2 = re.compile(r'^Call\\s+([A-Za-z_\\u4e00-\\u9fff][\\w\\u4e00-\\u9fff]*)\\s*$', re.I)\n# 子程序返回\nRETURN_RE = re.compile(r'^Return\\s*$', re.I)\n# 循环：Repeat N: / While 条件:（缩进子块）\nREPEAT_RE = re.compile(r'^Repeat\\s+(.+?)\\s*:\\s*$', re.I)\nWHILE_RE = re.compile(r'^While\\s+(.+?)\\s*:\\s*$', re.I)\n\nEND_KEYWORDS = {\"endif\", \"endchoose\"}\n\nIMAGE_EXT = (\".png\", \".jpg\", \".jpeg\", \".webp\", \".bmp\", \".gif\", \".avif\")\n\n\ndef name_is_reserved(name):\n    \"\"\"判断 name 是不是「不能当标签用」的保留字。\n\n    choose / if / else ... 这些词本来就不能做标签名；但 start 例外——\n    它是合法标签（Start: 作为剧本入口），所以从保留集里把 start 拎出去。\n    \"\"\"\n    return name.lower() in RESERVED and name.lower() != \"start\"\n\n\nclass Script(object):\n    \"\"\"一份解析好的剧本。\"\"\"\n\n    def __init__(self, path):\n        self.path = path\n        self.header = {}\n        self.body = []\n        self.ending = []\n        self.issues = []\n        self.pyblocks = []      # 抠出来的 python 代码块，语句里按序号引用\n\n    @property\n    def size(self):\n        return self.header.get(\"size\", (800, 600))\n\n    @property\n    def width(self):\n        return self.size[0]\n\n    @property\n    def height(self):\n        return self.size[1]\n\n    @property\n    def title(self):\n        return self.header.get(\"title\") or \\\n            os.path.splitext(os.path.basename(self.path))[0]\n\n    @property\n    def font(self):\n        return self.header.get(\"font\") or \"Microsoft YaHei\"\n\n    def error_count(self):\n        return len([i for i in self.issues if i.level == \"error\"])\n\n    def walk(self, stmts=None):\n        \"\"\"按顺序遍历所有语句（含嵌套分支里的）。\"\"\"\n        for s in (self.body if stmts is None else stmts):\n            yield s\n            if s[\"k\"] == \"if\":\n                for sub in self.walk(s[\"body\"]):\n                    yield sub\n                for sub in self.walk(s.get(\"else_body\") or []):\n                    yield sub\n\n\n# --------------------------------------------------------------------------- #\n# 工具\n# --------------------------------------------------------------------------- #\ndef _norm_quotes(s):\n    \"\"\"把全角引号（\" \" ' '）统一换成半角（\" '）。\n\n    设计稿通篇用全角引号，玩家照抄进 .stm 会解析失败；这里无脑纠正一遍，\n    免得用户每句台词都要手动切输入法。QUOTE_FIX 表里就是这两对映射。\n    \"\"\"\n    for a, b in QUOTE_FIX.items():\n        s = s.replace(a, b)\n    return s\n\n\ndef _dedent_code(code_lines):\n    \"\"\"去掉代码块整体的公共缩进（块写在 If 里面时，每行都会多 4 格）。\"\"\"\n    body = list(code_lines)\n    while body and not body[0].strip():\n        body.pop(0)\n    while body and not body[-1].strip():\n        body.pop()\n    pads = [len(ln) - len(ln.lstrip(\" \\t\")) for ln in body if ln.strip()]\n    cut = min(pads) if pads else 0\n    return [ln[cut:] if len(ln) >= cut else ln.lstrip() for ln in body]\n\n\ndef _extract_pyblocks(text, issues):\n    \"\"\"把内嵌的 python 代码块抠出来，原地换成占位行。\n\n    两种写法都认（缩进跟着外层，代码的共同缩进会被去掉）：\n\n        <                <python:\n        python:          print(\"1\")\n        print(\"1\")       >\n        >\n\n    冒号后面可以只写一个数字，表示「每行 print 之间隔几秒」，默认 3。\n    返回 (替换后的文本, [{\"code\": [...], \"delay\": 3.0, \"line\": 行号}, ...])\n    \"\"\"\n    lines = text.splitlines()\n    out, blocks = [], []\n    i = 0\n    while i < len(lines):\n        raw = lines[i]\n        s = raw.strip()\n        indent = raw[:len(raw) - len(raw.lstrip(\" \\t\"))]\n        head, spec, code_from = None, \"\", 0\n\n        m = PY_BLOCK_OPEN_RE.match(s)          # <python: 3   （开口和关键词同一行）\n        if m:\n            head, spec, code_from = i, m.group(1), i + 1\n        elif s == \"<\":                          # < 换行 然后  python:\n            j = i + 1\n            while j < len(lines) and not lines[j].strip():\n                j += 1\n            if j < len(lines):\n                km = PY_BLOCK_KW_RE.match(lines[j].strip())\n                if km:\n                    head, spec, code_from = j, km.group(1), j + 1\n\n        if head is None:\n            out.append(raw)\n            i += 1\n            continue\n\n        # 收集代码，直到单独一行的 >\n        j, code = code_from, []\n        while j < len(lines) and lines[j].strip() not in (\">\", \"<\/>\"):\n            code.append(lines[j])\n            j += 1\n        if j >= len(lines):\n            issues.append(Issue(head + 1, \"python 代码块没有写 > 收尾\",\n                                \"在代码最后单独写一行 >\"))\n            j = len(lines) - 1\n\n        delay = PY_DELAY_DEFAULT\n        txt = (spec or \"\").strip()\n        if txt:\n            dm = PY_DELAY_RE.match(txt)\n            if dm:\n                delay = max(0.0, min(PY_DELAY_MAX, float(dm.group(1))))\n            else:\n                issues.append(Issue(\n                    head + 1, \"python: 后面只认「隔几秒」，这里写的是：%s\" % txt[:20],\n                    \"写成 python: 3 表示每行隔 3 秒；要跑代码请写在下面几行\", \"warn\"))\n\n        blocks.append({\"code\": _dedent_code(code), \"delay\": delay,\n                       \"line\": head + 1, \"code_line\": code_from + 1})\n        out.append(indent + \"__STM_PYBLOCK_%d__\" % (len(blocks) - 1))\n        out.extend([\"\"] * (j - i))              # 补齐行数，保证行号不错位\n        i = j + 1\n    return \"\\n\".join(out), blocks\n\n\ndef _split_blocks(text, issues):\n    \"\"\"按顶层的 < ... > 切块。返回 [(起始行号, [(行号, 原文), ...]), ...]\"\"\"\n    blocks, cur = [], None\n    for n, raw in enumerate(text.splitlines(), 1):\n        s = raw.strip()\n        if s == \"<\":\n            if cur is not None:\n                issues.append(Issue(cur[0], \"有一段剧情块（< ... >）还没写结尾的 >\",\n                                    \"在它的最后单独写一行 > 收尾\"))\n            cur = [n, []]\n            continue\n        if s in (\">\", \"<\/>\"):  # 单个 > 或者 <\/> 都当块结束\n            if cur is None:\n                issues.append(Issue(n, \"这里多了一个 >，但前面没有对应的 < 开头\",\n                                    \"删掉这个 >，或在它前面补上 < 开块\"))\n            else:\n                blocks.append((cur[0], cur[1]))\n                cur = None\n            continue\n        if cur is not None:\n            cur[1].append((n, raw))\n    if cur is not None:\n        issues.append(Issue(cur[0], \"剧本读完了，但有一个 < 块一直没写 > 收尾\",\n                            \"在文件末尾补一行 >\"))\n        blocks.append((cur[0], cur[1]))\n    return blocks\n\n\ndef parse_args(s):\n    \"\"\"解析括号里的实参。容忍设计稿里漏掉的逗号（key=\"a\"key=\"b\"）。\"\"\"\n    args, kwargs = [], {}\n    i, n = 0, len(s)\n    while i < n:\n        if s[i] in \" \\t\\r\\n,\":\n            i += 1\n            continue\n        key = None\n        # key=值 和 key:值 两种写法都认（冒号写法是 AVG 用的：\n        # S.AVG-button(x:0, y:0, \"box\")）。唯一的例外是 http:// ——\n        # 冒号后面紧跟 // 的不当成 key，免得把 URL 撕成 key=\"http\"、值=\"//...\"\n        m = re.match(r\"([A-Za-z_]\\w*)\\s*([=:])\", s[i:])\n        if m and m.group(2) == \":\" and \\\n                s[i + m.end():].lstrip().startswith(\"//\"):\n            m = None\n        if m:\n            key = m.group(1)\n            i += m.end()\n        if i < n and s[i] == '\"':\n            j, buf = i + 1, []\n            while j < n:\n                if s[j] == \"\\\\\" and j + 1 < n:\n                    buf.append(s[j + 1])\n                    j += 2\n                    continue\n                if s[j] == '\"':\n                    break\n                buf.append(s[j])\n                j += 1\n            val = \"\".join(buf)\n            i = j + 1\n        else:\n            m = re.match(r\"[^,\\s)]+\", s[i:])\n            if not m:\n                i += 1\n                continue\n            val = m.group(0)\n            i += m.end()\n        if key:\n            kwargs[key] = val\n        else:\n            args.append(val)\n    return args, kwargs\n\n\ndef _indent_of(raw):\n    return len(raw) - len(raw.lstrip(\" \\t\"))\n\n\ndef _looks_like_image(v):\n    \"\"\"猜 v 是不是一个「图片路径」。\n\n    三种信号都认：以图片后缀结尾（.png 等）/ 含斜杠（路径）/ 含反斜杠。\n    S.character(\"...\") 拿到这种值就当立绘显示，否则当角色名（define）。\n    \"\"\"\n    v = (v or \"\").lower()\n    return v.endswith(IMAGE_EXT) or \"/\" in v or \"\\\\\" in v\n\n\ndef _prefix_issue(iss, base):\n    \"\"\"给被 include 文件的报错加上文件名前缀，方便定位到 chapter1.stm:行12。\"\"\"\n    if iss.line:\n        msg = \"%s:行%d %s\" % (base, iss.line, iss.message)\n    else:\n        msg = \"%s: %s\" % (base, iss.message)\n    return Issue(iss.line, msg, iss.hint, iss.level)\n\n\ndef _tag_file(stmts, base):\n    \"\"\"给 include 进来的语句打上原文件名（file 字段），递归进嵌套的 if/choose。\n\n    这样运行时报错、调试都能知道这句来自哪个文件；顶层剧本的语句不带 file 字段\n    （保持老行为）。\n    \"\"\"\n    out = []\n    for st in stmts:\n        st = dict(st)\n        st[\"file\"] = base\n        for key in (\"body\", \"else_body\"):\n            if st.get(key):\n                st[key] = _tag_file(st[key], base)\n        out.append(st)\n    return out\n\n\ndef _expand_include(raw, n, base_dir, incl_chain, issues):\n    \"\"\"处理 include \"x.stm\"：读目标文件、整体解析、把正文内联进来。\n\n    返回 (语句列表, [Issue, ...])。找不到 / 循环 include 都通过 Issue 报错，\n    **不崩溃**——主解析照常继续（缺文件的那段就当空）。\n    \"\"\"\n    target = raw.strip().replace(\"\\\\\", \"/\")\n    if base_dir:\n        target = os.path.join(base_dir, target)\n    target = os.path.abspath(target)\n    base = os.path.basename(target)\n\n    if os.path.isfile(target):\n        if target in incl_chain:\n            # 循环 include（A include B、B 又 include A）：报错并停止展开\n            return [], [Issue(n, \"%s: 检测到循环 include（%s 已经被包含过了）\"\n                                 % (base, base),\n                                 \"检查是不是 A include B、B 又 include A 了\")]\n        try:\n            with open(target, \"r\", encoding=\"utf-8-sig\") as f:\n                text = f.read()\n        except OSError as e:\n            return [], [Issue(n, \"%s: 读不了：%s\" % (base, e))]\n        # 嵌套 include 时把当前文件压进链，子文件里再 include 自己就报错\n        sub_chain = list(incl_chain) + [target]\n        sc2 = parse_text(text, target)\n        # 被 include 的文件不需要 Start:（入口只在主剧本里），这条提醒对它没有意义，\n        # 滤掉免得每 include 一个文件就多一条无用提示\n        out_issues = [_prefix_issue(iss, base) for iss in sc2.issues\n                      if \"没有 Start\" not in (getattr(iss, \"message\", \"\") or \"\")]\n        return _tag_file(sc2.body, base), out_issues\n\n    return [], [Issue(n, \"%s: 文件找不到（include 解析不到「%s」）\" % (base, raw),\n                      \"确认路径是相对当前剧本文件所在目录写的\")]\n\n\n# --------------------------------------------------------------------------- #\n# 语句解析\n# --------------------------------------------------------------------------- #\ndef _parse_lines(lines, issues, pyblocks=None, base_dir=None, incl_chain=None):\n    \"\"\"把 [(行号, 原文), ...] 解析成语句列表。缩进代表嵌套。\n\n    base_dir / incl_chain 给 include 用：base_dir 是当前文件所在目录（相对它解析\n    被包含文件），incl_chain 是已经展开过的文件绝对路径链（防循环）。\n    \"\"\"\n    if incl_chain is None:\n        incl_chain = []\n    items = []\n    for n, raw in lines:\n        if not raw.strip():\n            continue\n        items.append([n, _indent_of(raw), _norm_quotes(raw.strip())])\n\n    pos = [0]\n\n    def parse_block(indent, allow_empty=True, allow_end=True):\n        stmts = []\n        last_block = [False]      # 上一个语句是不是 If / Choose（决定 EndIf 归谁）\n        while pos[0] < len(items):\n            n, ind, s = items[pos[0]]\n            if ind < indent:\n                break\n            if ind > indent:\n                if allow_empty:\n                    issues.append(Issue(n, \"这一行缩进太深，可它前面没有 If / Choose 之类的结构收它\",\n                                        \"只有 If / Choose 里面的内容才需要缩进\"))\n                    pos[0] += 1\n                    continue\n                break\n\n            low = s.lower().rstrip(\":\").strip()\n\n            # --- python 代码块（_extract_pyblocks 留下的占位行）---\n            pm = PY_BLOCK_MARK_RE.match(s)\n            if pm:\n                pos[0] += 1\n                idx = int(pm.group(1))\n                pb = pyblocks[idx] if pyblocks and idx < len(pyblocks) else {}\n                stmts.append({\"k\": \"pycode\",\n                              \"code\": list(pb.get(\"code\") or []),\n                              \"delay\": pb.get(\"delay\", PY_DELAY_DEFAULT),\n                              \"code_line\": pb.get(\"code_line\") or (n + 1),\n                              \"line\": pb.get(\"line\") or n})\n                last_block[0] = False\n                continue\n\n            # --- 显式结束标记：只有真的在某个分支里才当结束，否则算多余的 ---\n            if low in END_KEYWORDS:\n                pos[0] += 1\n                if last_block[0]:\n                    # 紧接着前面那个 If / Choose，那就是给它收尾的，正常\n                    last_block[0] = False\n                    continue\n                if allow_end:\n                    break\n                issues.append(Issue(n, \"这里的 %s 有点多余：当前这层没有需要它收尾的 If / Choose\"\n                                    % s, \"如果不需要就删掉，或者检查缩进对不对\", \"warn\"))\n                continue\n            last_block[0] = False\n\n            # --- include 多文件剧本：解析期内联目标文件正文 ---\n            im = INCLUDE_RE.match(s)\n            if im:\n                pos[0] += 1\n                sub, sub_issues = _expand_include(im.group(1), n, base_dir,\n                                                  incl_chain, issues)\n                issues.extend(sub_issues)\n                stmts.extend(sub)\n                continue\n\n            # --- 子程序返回 Return（栈空时由 run() 结束剧本）---\n            if RETURN_RE.match(s):\n                pos[0] += 1\n                stmts.append({\"k\": \"return\", \"line\": n})\n                continue\n\n            # --- 子程序调用 Call \"标签\" / Call 标签 ---\n            cm = CALLSUB_RE.match(s) or CALLSUB_RE2.match(s)\n            if cm:\n                pos[0] += 1\n                stmts.append({\"k\": \"call_sub\", \"name\": cm.group(1), \"line\": n})\n                continue\n\n            # --- Repeat N: / While 条件: 循环（缩进子块）---\n            rm = REPEAT_RE.match(s)\n            if rm:\n                pos[0] += 1\n                if pos[0] < len(items) and items[pos[0]][1] > indent:\n                    body = parse_block(items[pos[0]][1], allow_empty=False)\n                else:\n                    body = []\n                    issues.append(Issue(n, \"Repeat 下面的循环体没缩进，引擎不知道要循环到哪\",\n                                        \"循环体往前缩进 4 格\"))\n                stmts.append({\"k\": \"repeat\", \"count\": rm.group(1).strip(),\n                              \"body\": body, \"line\": n})\n                continue\n\n            wm = WHILE_RE.match(s)\n            if wm:\n                pos[0] += 1\n                if pos[0] < len(items) and items[pos[0]][1] > indent:\n                    body = parse_block(items[pos[0]][1], allow_empty=False)\n                else:\n                    body = []\n                    issues.append(Issue(n, \"While 下面的循环体没缩进，引擎不知道要循环到哪\",\n                                        \"循环体往前缩进 4 格\"))\n                stmts.append({\"k\": \"while\", \"cond\": wm.group(1).strip(),\n                              \"body\": body, \"line\": n})\n                continue\n\n            # --- Else: ---\n            if ELSE_RE.match(s):\n                pos[0] += 1\n                stmts.append({\"k\": \"else\", \"line\": n})\n                continue\n\n            # --- Choose: ---\n            if CHOOSE_RE.match(s):\n                pos[0] += 1\n                opts, decl_line = [], n\n                while pos[0] < len(items):\n                    on, oind, osx = items[pos[0]]\n                    if oind > indent:\n                        opts.extend(re.findall(r'\"([^\"]*)\"', osx))\n                        pos[0] += 1\n                        continue\n                    if oind == indent and OPTIONS_RE.match(osx):\n                        opts.extend(re.findall(r'\"([^\"]*)\"', osx))\n                        pos[0] += 1\n                        continue\n                    break\n                if not opts:\n                    issues.append(Issue(decl_line, \"Choose: 下面没写任何选项\",\n                                        '在它下面写： \"选项A\" \"选项B\"'))\n                stmts.append({\"k\": \"choose\", \"options\": opts, \"line\": decl_line})\n                last_block[0] = True\n                continue\n\n            # --- If cond: ---\n            m = IF_RE.match(s)\n            if m:\n                cond = m.group(1)\n                pos[0] += 1\n                if pos[0] < len(items) and items[pos[0]][1] > indent:\n                    body = parse_block(items[pos[0]][1], allow_empty=False)\n                else:\n                    body = []\n                    issues.append(Issue(n, \"If 里面的内容既没缩进也没写 EndIf，引擎只能猜哪里结束\",\n                                        \"正文往前缩进 4 格，或者显式写 EndIf 收尾\"))\n                    while pos[0] < len(items):\n                        nn, nind, ns = items[pos[0]]\n                        nlow = ns.lower().rstrip(\":\").strip()\n                        if nind <= indent and (IF_RE.match(ns) or ELSE_RE.match(ns)\n                                               or CHOOSE_RE.match(ns)\n                                               or QUESTION_RE.match(ns)\n                                               or LABEL_RE.match(ns)\n                                               or nlow in END_KEYWORDS):\n                            break\n                        stay = pos[0]\n                        body.extend(parse_block(nind, allow_empty=False))\n                        if pos[0] == stay:\n                            break\n                else_body = []\n                if pos[0] < len(items) and items[pos[0]][2].lower().startswith(\"else\"):\n                    pos[0] += 1\n                    if pos[0] < len(items) and items[pos[0]][1] > indent:\n                        else_body = parse_block(items[pos[0]][1], allow_empty=False)\n                stmts.append({\"k\": \"if\", \"cond\": cond, \"body\": body,\n                              \"else_body\": else_body, \"line\": n})\n                last_block[0] = True\n                continue\n\n            # --- Question: ---\n            m = QUESTION_RE.match(s)\n            if m:\n                pos[0] += 1\n                prompt = m.group(1).strip()\n                # 提示文字也可以写在 Question: 的下一行（缩进一个 \"...\"）\n                if not prompt and pos[0] < len(items) and items[pos[0]][1] > indent:\n                    on, _oi, osx = items[pos[0]]\n                    if BARE_SAY_RE.match(osx):\n                        prompt = osx\n                        pos[0] += 1\n                stmts.append({\"k\": \"question\", \"prompt\": prompt, \"line\": n})\n                continue\n\n            # --- SET 名字: （AVG 绘图变量，缩进块里是海龟绘图指令）---\n            m = AVG_SET_RE.match(s)\n            if m:\n                pos[0] += 1\n                # 收集下面所有缩进更深的行作为绘图块（和 If / Repeat 收块的规则一致）\n                body_lines = []\n                while pos[0] < len(items) and items[pos[0]][1] > indent:\n                    body_lines.append(items[pos[0]][2])\n                    pos[0] += 1\n                if not body_lines:\n                    issues.append(Issue(n, \"SET %s: 下面没写任何绘图指令\"\n                                        % m.group(1),\n                                        \"在它下面缩进写 go(10px)、left(90) 这样的指令\"))\n                # 指令编译：写错的行在这里就报出来（带行号），不拖到运行时\n                ops, op_issues = avgmod.compile_ops(body_lines)\n                for ln_text, err in op_issues:\n                    issues.append(Issue(n, \"SET %s: %s\" % (m.group(1), err),\n                                        \"对照 stmg/avg.py 文件头的语法说明改一下\"))\n                stmts.append({\"k\": \"avg_def\", \"name\": m.group(1),\n                              \"ops\": ops, \"line\": n})\n                continue\n\n            # --- SET name = value ---\n            m = SET_RE.match(s)\n            if m:\n                pos[0] += 1\n                stmts.append({\"k\": \"set\", \"name\": m.group(1),\n                              \"expr\": m.group(2).strip(), \"line\": n})\n                continue\n\n            # --- stm.os(...) —— 受控文件操作（DDLC 式彩蛋用）---\n            m = STM_OS_RE.match(s)\n            if m:\n                inner = m.group(1)\n                im = STM_OS_INNER_RE.match(inner)\n                if not im:\n                    issues.append(Issue(\n                        n, \"看不懂 stm.os 的写法：%s\" % inner[:40],\n                        '照着 STM.os(read(\"路径\")) 或 STM.os(revision(\"路径\"),\"旧\"to\"新\") 写'))\n                    pos[0] += 1\n                    continue\n                op, fpath, find, replace = im.group(1), im.group(2), \\\n                    im.group(3), im.group(4)\n                op = op.lower()\n                if op not in (\"read\", \"create\", \"remove\", \"revision\"):\n                    issues.append(Issue(\n                        n, \"stm.os 只支持 read / create / remove / revision，这里却是：%s\" % op,\n                        \"把操作改成这四种之一\"))\n                    pos[0] += 1\n                    continue\n                if op == \"revision\" and find is None:\n                    issues.append(Issue(\n                        n, \"revision 少写了要替换的内容\",\n                        '写全：stm.os(revision(\"x\"),\"旧\"to\"新\")'))\n                    pos[0] += 1\n                    continue\n                stmts.append({\"k\": \"stm_os\", \"op\": op, \"path\": fpath,\n                              \"find\": find, \"replace\": replace, \"line\": n})\n                pos[0] += 1\n                continue\n\n            # --- 函数调用 S.play(...) / R.api(...) / S.AVG-button(...) ---\n            m = CALL_RE.match(s)\n            if m:\n                pos[0] += 1\n                # 方法名里的连字符统一换成下划线：AVG-button -> AVG_button，\n                # 后面所有处理（do_call 等）只认下划线版本。\n                target = m.group(1).replace(\"-\", \"_\")\n                raw_args = m.group(2)\n                args, kwargs = parse_args(raw_args)\n                parts = target.split(\".\")\n                obj = \".\".join(parts[:-1]) if len(parts) > 1 else \"\"\n                method = parts[-1]\n                if obj.upper() == \"S\" and method.lower() == \"character\":\n                    val = args[0] if args else \"\"\n                    if _looks_like_image(val):\n                        # 多张立绘可以同时在场，靠 tag 区分，pos 决定站哪\n                        stmts.append({\"k\": \"sprite\", \"path\": val, \"line\": n,\n                                      \"args\": args, \"kwargs\": kwargs})\n                    else:\n                        stmts.append({\"k\": \"define\", \"name\": val, \"line\": n})\n                    continue\n                stmts.append({\"k\": \"call\", \"obj\": obj, \"method\": method,\n                              \"args\": args, \"kwargs\": kwargs, \"line\": n})\n                continue\n\n            # --- 赋值 name = value ---\n            m = ASSIGN_RE.match(s)\n            if m:\n                pos[0] += 1\n                stmts.append({\"k\": \"set\", \"name\": m.group(1),\n                              \"expr\": m.group(2).strip(), \"line\": n})\n                continue\n\n            # --- Start: / 普通标签 ---\n            m = LABEL_RE.match(s)\n            if m and not name_is_reserved(m.group(1)):\n                pos[0] += 1\n                stmts.append({\"k\": \"label\", \"name\": m.group(1), \"line\": n})\n                continue\n\n            # --- 对白 ---\n            m = SAY_RE.match(s)\n            if m:\n                pos[0] += 1\n                stmts.append({\"k\": \"say\", \"who\": m.group(\"who\").strip(),\n                              \"text\": m.group(\"text\"), \"line\": n})\n                continue\n            if BARE_SAY_RE.match(s):\n                pos[0] += 1\n                stmts.append({\"k\": \"say\", \"who\": None, \"text\": s, \"line\": n})\n                continue\n\n            issues.append(Issue(n, \"这一行没看懂：%s\" % s[:40],\n                                \"对照 README 的语法说明检查一下写法\"))\n            pos[0] += 1\n        return stmts\n\n    return parse_block(0, allow_end=False)\n\n\ndef _parse_header(lines, issues):\n    \"\"\"解析剧本开头的「名称=值」设置块（size / title / font / lang ...）。\n\n    写错的行报「不是名称=值」；size 容错很大——large / size / resolution\n    三个键都认，分隔符接受 x / X / * / ×。识别不出时退回默认 800x600。\n    title / font / ver / lang 给不出就填默认值。\n    \"\"\"\n    header = {}\n    for n, raw in lines:\n        s = _norm_quotes(raw.strip())\n        if not s:\n            continue\n        m = HEADER_KV_RE.match(s)\n        if not m:\n            issues.append(Issue(n, \"剧本开头的设置里有一行不是「名称=值」：%s\" % s[:30],\n                                \"头部每行写成 名称=值，例如 size=800x600\"))\n            continue\n        k, v = m.group(1), m.group(2).strip().strip('\"')\n        header[k.lower()] = v\n\n    size = header.get(\"large\") or header.get(\"size\") or header.get(\"resolution\") or \"800x600\"\n    m = re.match(r\"\\s*(\\d+)\\s*[xX*\\u00d7]\\s*(\\d+)\", size)\n    if m:\n        header[\"size\"] = (int(m.group(1)), int(m.group(2)))\n    else:\n        issues.append(Issue(None, \"分辨率看不懂：%s\" % size, \"写成例如 800x600 这种\"))\n        header[\"size\"] = (800, 600)\n\n    header.setdefault(\"title\", \"\")\n    header.setdefault(\"font\", \"Microsoft YaHei\")\n    header.setdefault(\"ver\", \"1.0.0\")\n    header.setdefault(\"lang\", \"cn\")\n    return header\n\n\ndef parse_file(path):\n    \"\"\"从磁盘读一个 .stm 文件并解析成 Script。等价 parse_text(读到的文本, path)。\"\"\"\n    with open(path, \"r\", encoding=\"utf-8-sig\") as f:\n        text = f.read()\n    return parse_text(text, path)\n\n\ndef parse_text(text, path=\"<memory>\"):\n    sc = Script(path)\n    # include 相对「当前剧本文件所在目录」解析；<memory> 之类无路径的就相对当前目录\n    base_dir = os.path.dirname(os.path.abspath(path)) if path else \"\"\n    incl_chain = []\n    if \"\\u201c\" in text or \"\\u201d\" in text:\n        sc.issues.append(Issue(None, \"剧本里用了中文引号 “ ”，已经帮你换成英文引号了\",\n                               \"以后直接打英文半角引号更稳妥\", \"warn\"))\n    text = COMMENT_RE.sub(\"\", text)\n    # python 代码块也是 < ... > 包的，不先抠出来的话会被 _split_blocks 当成剧情块切开\n    text, sc.pyblocks = _extract_pyblocks(text, sc.issues)\n    blocks = _split_blocks(text, sc.issues)\n    if not blocks:\n        sc.issues.append(Issue(None, \"剧本里没找到任何 < ... > 剧情块\",\n                               \"用 < 和 > 把正文包起来\"))\n        return sc\n\n    remaining = list(blocks)\n\n    # 第一块到底是头还是正文？\n    # 头部只认「名称=值」，所以：出现标签行或 python 代码块 -> 一定是正文；\n    # 否则看「名称=值」占了多大比例，过半才算头部 —— 这样头部里写错一行仍会\n    # 按头部报出「这行不是名称=值」，而整块剧情不会被误判成头。\n    # （「Start」大小写不敏感，写成小写 start 也认）\n    first = remaining[0]\n    nonblank = [(n, l) for n, l in first[1] if l.strip()]\n    joined = \"\\n\".join(l for _, l in nonblank)\n    kv = sum(1 for _, l in nonblank\n             if HEADER_KV_RE.match(_norm_quotes(l.strip())))\n    has_label = any(LABEL_RE.match(l.strip()) for _, l in nonblank)\n    is_body = (has_label or PY_BLOCK_MARK_RE.search(joined)\n               or (nonblank and kv * 2 < len(nonblank)))\n\n    if is_body:\n        sc.body = _parse_lines(first[1], sc.issues, sc.pyblocks, base_dir, incl_chain)\n        remaining.pop(0)\n    else:\n        sc.header = _parse_header(first[1], sc.issues)\n        remaining.pop(0)\n        if remaining:\n            sc.body = _parse_lines(remaining[0][1], sc.issues, sc.pyblocks,\n                                   base_dir, incl_chain)\n            remaining.pop(0)\n\n    if remaining:\n        end_lines = []\n        for _, ls in remaining:\n            end_lines.extend(ls)\n        sc.ending = _parse_lines(end_lines, sc.issues, sc.pyblocks,\n                                 base_dir, incl_chain)\n\n    if not sc.body:\n        sc.issues.append(Issue(None, \"正文是空的，游戏一开场就结束了\",\n                               \"在 Start: 下面写点剧情\"))\n\n    _validate(sc)\n    return sc\n\n\ndef _validate(sc):\n    \"\"\"静态检查。设计稿里点名「未定义角色就直接让角色说话」算错误。\"\"\"\n    defined = set()\n    labels = set()\n    options = set()\n    avg_shapes = set()          # SET 名字: 定义过的 AVG 绘图变量名\n\n    # AVG 用的收集器：walk() 只递归 if 的分支，Repeat / While 里的语句它不进，\n    # 这里干脆按语句 dict 递归一遍，把嵌套多深的 avg_def / avg_button 都翻出来。\n    def _avg_scan(stmts):\n        for st in stmts or []:\n            if not isinstance(st, dict):\n                continue\n            if st.get(\"k\") == \"avg_def\" and st.get(\"name\"):\n                avg_shapes.add(st[\"name\"])\n            for key in (\"body\", \"else_body\"):\n                if st.get(key):\n                    _avg_scan(st[key])\n\n    _avg_scan(sc.body)\n    _avg_scan(sc.ending)\n\n    for s in sc.walk():\n        if s[\"k\"] == \"define\" and s[\"name\"]:\n            defined.add(s[\"name\"])\n        elif s[\"k\"] == \"label\":\n            labels.add(s[\"name\"])\n        elif s[\"k\"] == \"choose\":\n            options.update(s[\"options\"])\n\n    for s in sc.walk():\n        if s[\"k\"] == \"say\" and s[\"who\"] and s[\"who\"] not in defined:\n            sc.issues.append(Issue(\n                s[\"line\"], \"角色「%s」还没登场就开口说话了\" % s[\"who\"],\n                '先在 Start: 下面用 S.character(\"%s\") 介绍一下' % s[\"who\"]))\n        if s[\"k\"] == \"if\":\n            cond = s[\"cond\"].strip()\n            if cond.startswith('\"') and cond.endswith('\"') and len(cond) > 1:\n                target = cond[1:-1]\n                if options and target not in options:\n                    sc.issues.append(Issue(\n                        s[\"line\"], \"If 里判断的选项「%s」，在选项里没出现过\" % target,\n                        \"确认 Choose 里的选项文字和这里完全一致\", \"warn\"))\n        if s[\"k\"] == \"pycode\" and not s.get(\"code\"):\n            sc.issues.append(Issue(\n                s[\"line\"], \"python 代码块里一行代码都没有\",\n                \"在 python: 下面写代码，或者把这个块删掉\", \"warn\"))\n        # S.AVG-button(x, y, \"形状\")：形状必须是内置的 box/circle，\n        # 或者某个 SET 名字: 定义过的绘图变量。写了个谁都不认识的名字\n        # 不会崩（运行时静默跳过），但八成是拼错了，提前吼一声。\n        if s[\"k\"] == \"call\" and s[\"obj\"].upper() == \"S\" \\\n                and s[\"method\"].lower() == \"avg_button\":\n            shape = s[\"kwargs\"].get(\"shape\")\n            if shape is None:\n                # 没写 shape= 时形状在第 3 个位置参数；写法是 x:0,y:0,\"box\"\n                # 这种（坐标走 kwargs）时形状落在第 1 个位置参数\n                if len(s[\"args\"]) >= 3:\n                    shape = s[\"args\"][2]\n                elif s[\"args\"] and (\"x\" in s[\"kwargs\"] or \"y\" in s[\"kwargs\"]):\n                    shape = s[\"args\"][0]\n            if isinstance(shape, str) and shape.strip('\"') \\\n                    and shape.strip('\"').lower() not in (\"box\", \"circle\") \\\n                    and shape.strip('\"') not in avg_shapes:\n                sc.issues.append(Issue(\n                    s[\"line\"], \"S.AVG-button 的形状「%s」既不是内置的 box/circle，\"\n                               \"也没有 SET 定义过\" % shape.strip('\"'),\n                    '先用 SET %s: 定义这个形状的画法，或者改用 \"box\" / \"circle\"'\n                    % shape.strip('\"'), \"warn\"))\n        if s[\"k\"] == \"call\" and s[\"method\"].lower() == \"python\" \\\n                and s[\"obj\"].upper() in (\"STM\", \"STMG\"):\n            from .stdlib_api import check_library\n            ok, why = check_library(s[\"args\"][0] if s[\"args\"] else \"\")\n            if not ok:\n                sc.issues.append(Issue(\n                    s[\"line\"], \"stmg.python 用不了：%s\" % why,\n                    '库名要写白名单里的；不需要库就写 stmg.python(\"none\")'))\n        if s[\"k\"] == \"call\" and s[\"obj\"].upper() == \"R\" and s[\"method\"] == \"api\":\n            key = s[\"kwargs\"].get(\"key\", \"\")\n            if key and key != \"option\" and not key.startswith(\"http\") and len(key) < 12:\n                sc.issues.append(Issue(\n                    s[\"line\"], \"R.api 的 key 好像是随便填的，太短了\",\n                    '正式发布请写 key=option，把密钥放进 options.stm', \"warn\"))\n    if labels and not any(l.lower() == \"start\" for l in labels):\n        sc.issues.append(Issue(None, \"正文里没有 Start: 标记\",\n                               \"没有也没关系，游戏会直接从头一句开始；想明确起点就加 Start:\", \"warn\"))\n","/stmg_root/stmg/runtime.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 运行时 —— 把语句树解释成一条「事件流」。\n\n用生成器实现：调用方 `next()` 拿事件，`send()` 把玩家的回答塞回去。\n这样渲染层不用关心剧本结构，剧本也不用关心窗口。\n\n事件类型：\n    say      一句台词 / 旁白          who(可为 None), text, color\n    choose   等玩家选                options\n    question 等玩家打字              prompt\n    bg       换背景                  path\n    picture  背景上的图片层          path(空则清除)\n    sprite   立绘                    path(空则隐藏)\n    bgm/se/voice  音频               path, loop\n    stop/hide    停音频 / 隐藏图层   what\n    transition  转场遮罩              kind, dur\n    toast    右上角提示              text\n    wait     停一会儿再往下           dur    （python 代码块逐行显示用）\n    python   STM.python 载入         name\n    avg      AVG 绘图层              action(draw/clear), shape, x, y, color,\n                                      size, width, ops   （第 3 期新增）\n    fatal    跑不动了                message, trace\n    end      剧本结束\n\"\"\"\n\nimport contextlib\nimport io\nimport os\nimport random\nimport re\nimport types\n\nfrom . import avg, pack, save as savemod, stdlib_api, stmos\nfrom .errors import STMFatal, format_exception\nfrom .markdown import strip_quotes\nfrom .parser import PY_DELAY_DEFAULT\n\n# python 代码块一次最多往右上角显示几行，免得一个死循环刷爆提示\nPY_MAX_LINES = 30\n\nNAME_COLORS = [\"#ff88bb\", \"#7fb3ff\", \"#6fd6a8\", \"#ffc44d\",\n               \"#c79bff\", \"#ff9d7a\", \"#5fc9d6\"]\n\nSAFE_BUILTINS = {\n    \"abs\": abs, \"min\": min, \"max\": max, \"len\": len, \"str\": str,\n    \"int\": int, \"float\": float, \"round\": round, \"bool\": bool,\n    \"range\": range, \"sum\": sum, \"sorted\": sorted, \"list\": list,\n    \"dict\": dict, \"enumerate\": enumerate, \"zip\": zip,\n}\n\n# 回放感知随机：\n#   - 正常跑：把每次随机数写进 answers 流（(\"rand\", v)），随存档一起保存；\n#   - 回放（读档重放）时：RAND 不再新抽，而是按记录原样吐出，\n#     于是带随机分支的剧情重载后走向完全一致。\n# RAND 需要访问「当前 Runtime 的回放状态」，但 SAFE_BUILTINS 是模块级共享表，\n# 所以函数体通过全局 _ACTIVE_RUNTIME 在求值时拿到实例（引擎单线程，安全）。\n_ACTIVE_RUNTIME = None\n\n\ndef RAND(a, b):\n    \"\"\"回放感知随机：返回 [a, b] 闭区间内的整数（含两端）。\"\"\"\n    rt = _ACTIVE_RUNTIME\n    if rt is not None:\n        return rt._rand_draw(a, b)\n    return random.randint(int(a), int(b))\n\n\n# 把随机函数加进安全内建表，让剧本表达式里能直接写 RAND(1,6) / randint(1,6)\nSAFE_BUILTINS = dict(SAFE_BUILTINS)\nSAFE_BUILTINS[\"randint\"] = RAND\nSAFE_BUILTINS[\"RAND\"] = RAND\n\nIDENT_RE = re.compile(r\"^[A-Za-z_\\u4e00-\\u9fff]\\w*$\")\nNUM_RE = re.compile(r\"^-?\\d+(?:\\.\\d+)?$\")\n\n\ndef _is_str_literal(s):\n    \"\"\"s 是不是「一个完整的字符串字面量」。\n\n    `\"你好\"` 是；`\"你好\" + STM.ANSWER` 不是（里面有第二对引号）。\n    分不清这两种，拼字符串就永远会被当成普通文本原样打出来。\n    \"\"\"\n    if not isinstance(s, str) or len(s) < 2:\n        return False\n    if not (s[0] == '\"' and s[-1] == '\"'):\n        return False\n    return '\"' not in s[1:-1]\n\n\nclass JumpSignal(Exception):\n    \"\"\"S.jump(\"标签\") 内部用。\"\"\"\n\n    def __init__(self, index):\n        Exception.__init__(self)\n        self.index = index\n\n\nclass ReturnSignal(Exception):\n    \"\"\"子程序返回（Call / Return 内部用）。\n\n    在子程序体内被 call_sub 的 try 接住；冒泡到 run() 顶层时表示「栈空」，\n    等于结束整个剧本（不崩）。\n    \"\"\"\n\n\nclass Runtime(object):\n    \"\"\"把解析好的「语句树」解释成一条「事件流」的解释器。\n\n    核心机制是 Python 生成器——调用方用 next() 拿下一个事件，用 send()\n    把玩家的选择 / 输入塞回来。这样渲染层（pygame / 网页）完全不用关心\n    剧本结构，剧本也不用关心窗口和音频怎么播。\n\n    关键设计点：\n      * 所有「分支 / 随机 / 联网 / 文件操作」都做成**可重放**：运行时的每一步\n        玩家输入、骰子结果、联网返回都会写进 self.answers 流并随存档保存，\n        读档时整条流回放出来，于是带随机分支的剧情重开后走向完全一致\n        （见 _rand_draw / _take_answer / _take_record）。\n      * 开发模式专属：STM.python / python 代码块 / 调试提示，发布版整块跳过或静默。\n      * 副作用（背景 / 立绘 / 音频 / AVG 绘图）产出的事件里自带全部信息，\n        网页版拿到事件就能直接画，不用回头问 Python 引擎要数据。\n    \"\"\"\n\n    def __init__(self, script, options=None, dev_mode=True):\n        self.script = script\n        self.options = options\n        self.dev_mode = dev_mode\n        self.root = os.path.dirname(os.path.abspath(script.path))\n\n        self.STM = types.SimpleNamespace(Q=\"\", ANSWER=\"\", NAME=\"\", API=None, OS=\"\")\n        self.vars = {\"STM\": self.STM, \"R\": types.SimpleNamespace(RESULT=None)}\n        self.names = {}\n        self.chosen = set()\n        self.last_choice = None\n        self.history = []\n        self.answers = []          # 存档用：[(\"choose\", 选项名), (\"question\", 输入)]\n        self._libraries = {}\n        self._lib_modules = {}     # stmg.python(\"math\") 声明过的库：名字 -> 模块\n        self.quiet = False         # True = 读档重放中：照跑代码，但不重复弹提示\n        self._replay = []\n        self._replay_i = 0\n        self._labels = {s[\"name\"]: i for i, s in enumerate(script.body)\n                        if s[\"k\"] == \"label\"}\n        # 子程序表：标签名 -> 该标签到下一个标签之间的语句列表（Call 时整段执行）\n        self._subs = {}\n        body = self.script.body\n        i = 0\n        while i < len(body):\n            if body[i][\"k\"] == \"label\":\n                name = body[i][\"name\"]\n                j = i + 1\n                sub = []\n                while j < len(body) and body[j][\"k\"] != \"label\":\n                    sub.append(body[j])\n                    j += 1\n                self._subs[name] = sub\n                i = j\n            else:\n                i += 1\n        # 副作用回放计数（R.api / stm.os 的序号，仅用于 api_result/os_result 事件的 n 字段）\n        self._api_n = 0\n        self._os_n = 0\n\n        # AVG 绘图变量表：SET 名字: 定义的海龟绘图指令（名字 -> ops 列表）。\n        # 解析期已经把指令编译好了（stmg/avg.py 的 compile_ops），\n        # 这里只管登记，S.AVG-button(x, y, \"名字\") 时把 ops 塞进事件里。\n        self.avg_shapes = {}\n        # 语音自动挂载用的计数：每个角色第几句、全局第几句\n        self._say_char_count = {}\n        self._say_global_count = 0\n\n        # 成就系统：已解锁集合（跨会话持久化，按剧本标题区分）。\n        # 一开始从存档里读出来；运行中新解锁的会立刻写回。\n        self.unlocked = savemod.load_achievements(self.root, self.script.title)\n        # CG 回廊：看过的背景 / 叠图，跨会话持久化（供标题界面的回廊展示）\n        self.seen_cg = savemod.load_cg(self.root, self.script.title)\n\n    # ------------------------------------------------------------------ #\n    # 求值\n    # ------------------------------------------------------------------ #\n    def eval_expr(self, expr):\n        expr = (expr or \"\").strip()\n        if not expr:\n            return \"\"\n        if _is_str_literal(expr):\n            return expr[1:-1]\n        if NUM_RE.match(expr):\n            return float(expr) if \".\" in expr else int(expr)\n        env = dict(self.vars)\n        env.setdefault(\"STM\", self.STM)\n        global _ACTIVE_RUNTIME\n        _ACTIVE_RUNTIME = self\n        try:\n            return eval(expr, {\"__builtins__\": SAFE_BUILTINS}, env)\n        except NameError:\n            if IDENT_RE.match(expr):\n                # 没定义过的裸词，当字符串处理，别直接崩\n                return expr\n            raise STMFatal(\"算式里有没定义过的东西：%s\" % expr)\n        except ZeroDivisionError:\n            raise STMFatal(\"除零了：%s\" % expr)\n        except Exception as e:                       # noqa: BLE001\n            raise STMFatal(\"算式算不出来：%s（%s）\" % (expr, e))\n        finally:\n            # 求值结束（无论成功或异常）都清掉，避免指向已失效的 Runtime\n            _ACTIVE_RUNTIME = None\n\n    def eval_cond(self, cond):\n        cond = (cond or \"\").strip()\n        if not cond:\n            return True\n        if _is_str_literal(cond):\n            # If \"选项1\": —— 判断有没有选过这个名字\n            return cond[1:-1] in self.chosen\n        return bool(self.eval_expr(cond))\n\n    def resolve(self, path):\n        \"\"\"把剧本里的相对路径变成绝对路径；找不到就原样返回，交给渲染层画占位。\"\"\"\n        if not path:\n            return \"\"\n        p = path.replace(\"\\\\\", \"/\")\n        if os.path.isabs(p) and os.path.exists(p):\n            return p\n        pk = pack.active()\n        if pk is not None and pk.has(p):\n            return pack.PREFIX + p\n        return os.path.join(self.root, p)\n\n    # ------------------------------------------------------------------ #\n    # 主循环\n    # ------------------------------------------------------------------ #\n    def run(self, replay=None):\n        self._replay = list(replay or [])\n        self._replay_i = 0\n        body = self.script.body\n        i = 0\n        try:\n            while True:\n                try:\n                    # 必须用 yield from：它会把 send() 送进来的值一路转交给\n                    # 最里面那个 yield，写成 for ... yield 的话玩家输入会被丢掉。\n                    yield from self.exec_block(body[i:])\n                    break\n                except JumpSignal as j:\n                    i = j.index\n                    continue\n            if self.script.ending:\n                yield from self.exec_block(self.script.ending)\n        except ReturnSignal:\n            # 顶层的 Return（调用栈空）：直接结束剧本，不跑结尾块\n            pass\n        except STMFatal as e:\n            yield {\"t\": \"fatal\", \"message\": str(e), \"trace\": \"\"}\n            return\n        except Exception as e:                       # noqa: BLE001\n            yield {\"t\": \"fatal\", \"message\": \"%s: %s\" % (type(e).__name__, e),\n                   \"trace\": format_exception(e) if self.dev_mode else \"\"}\n            return\n        yield {\"t\": \"end\"}\n\n    def exec_block(self, stmts):\n        \"\"\"顺序执行一段语句列表，把每条翻译成的事件 yield 出去。\n\n        这是整个「语句 -> 事件」翻译的核心分派：say / choose / if / set /\n        call_sub / repeat / while / call ... 每种语句 k 都在这分支处理。\n        遇到 S.jump / Return 会通过 JumpSignal / ReturnSignal 异常跳出，\n        交给 run() 顶层统一处理标签跳转和子程序返回。\n        \"\"\"\n        for s in stmts:\n            k = s[\"k\"]\n\n            if k == \"say\":\n                text = self._say_text(s[\"text\"])\n                who = s[\"who\"]\n                # 语音自动挂载：有角色名且开关打开时，先试着找配音，命中就播\n                for vev in self._auto_voice(who):\n                    yield vev\n                ev = {\"t\": \"say\", \"who\": who, \"text\": text, \"line\": s[\"line\"]}\n                if who:\n                    if who not in self.names:\n                        self.names[who] = NAME_COLORS[len(self.names) % len(NAME_COLORS)]\n                    ev[\"color\"] = self.names[who]\n                self.history.append((who or \"\", text))\n                yield ev\n\n            elif k == \"choose\":\n                ev = {\"t\": \"choose\", \"options\": list(s[\"options\"]),\n                      \"line\": s[\"line\"]}\n                ans = self._take_answer()\n                if ans is None:\n                    ans = yield ev\n                    # 存档用：把选择记进 answers 流。记**索引**而不是文本，\n                    # 这样多语言剧本（同一句话在不同语言里选项文字不同）也能\n                    # 用同一份存档正确重放。老存档里存的是文本，_take_answer\n                    # 原样吐回来，choose 分支照样兼容。\n                    if isinstance(ans, str) and ans in ev[\"options\"]:\n                        self.answers.append((\"choose\", ev[\"options\"].index(ans)))\n                    else:\n                        self.answers.append((\"choose\", ans))\n                self.chosen.add(ans)\n                self.last_choice = ans\n                if not isinstance(ans, str):\n                    ans = ev[\"options\"][ans] if isinstance(ans, int) and \\\n                        ans < len(ev[\"options\"]) else str(ans)\n                    self.chosen.add(ans)\n                    self.last_choice = ans\n\n            elif k == \"if\":\n                if self.eval_cond(s[\"cond\"]):\n                    yield from self.exec_block(s[\"body\"])\n                elif s.get(\"else_body\"):\n                    yield from self.exec_block(s[\"else_body\"])\n\n            elif k == \"else\":\n                continue\n\n            elif k == \"set\":\n                self._assign(s[\"name\"], self.eval_expr(s[\"expr\"]))\n\n            elif k == \"question\":\n                prompt = strip_quotes(s[\"prompt\"]) if s[\"prompt\"] else \"\"\n                if prompt:\n                    self.STM.Q = prompt\n                ev = {\"t\": \"question\", \"prompt\": self.STM.Q or \"请输入\",\n                      \"line\": s[\"line\"]}\n                ans = self._take_answer()\n                if ans is None:\n                    ans = yield ev\n                    self.answers.append((\"question\", ans))\n                self.STM.ANSWER = ans\n                self.vars[\"STM.ANSWER\"] = ans\n\n            elif k == \"define\":\n                name = s[\"name\"]\n                if name and name not in self.names:\n                    self.names[name] = NAME_COLORS[len(self.names) % len(NAME_COLORS)]\n\n            elif k == \"sprite\":\n                yield from self._sprite_event(s[\"path\"], s.get(\"args\") or [],\n                                              s.get(\"kwargs\") or {})\n\n            elif k == \"label\":\n                continue\n\n            elif k == \"return\":\n                # 子程序返回：冒泡给最近的 Call 接住；到顶层就结束剧本\n                raise ReturnSignal()\n\n            elif k == \"call_sub\":\n                # 子程序调用：整段执行，遇到 Return 正常返回；找不到标签直接报错\n                sub = self._subs.get(s[\"name\"])\n                if sub is None:\n                    raise STMFatal('Call \"%s\" 找不到这个子程序标签' % s[\"name\"],\n                                   s[\"line\"])\n                try:\n                    yield from self.exec_block(sub)\n                except ReturnSignal:\n                    pass\n\n            elif k == \"repeat\":\n                # Repeat N: N 可以是表达式，用 eval_expr 求值；负数/0 一次都不跑\n                try:\n                    count = int(self.eval_expr(s[\"count\"]))\n                except STMFatal:\n                    count = 0\n                for _ in range(max(0, count)):\n                    yield from self.exec_block(s[\"body\"])\n\n            elif k == \"while\":\n                # While 条件: 每次循环前重新求值；硬上限 10000 次防死循环\n                guard = 0\n                while self.eval_cond(s[\"cond\"]):\n                    guard += 1\n                    if guard > 10000:\n                        raise STMFatal(\n                            \"While 循环超过 10000 次，可能写成了死循环\", s[\"line\"])\n                    yield from self.exec_block(s[\"body\"])\n\n            elif k == \"call\":\n                yield from self.do_call(s)\n\n            elif k == \"avg_def\":\n                # SET 名字: 定义的 AVG 绘图变量：登记进表里就完事，\n                # 不产事件——「定义」本身不是画面变化，画的时候（S.AVG-button）才发。\n                self.avg_shapes[s[\"name\"]] = s.get(\"ops\") or []\n\n            elif k == \"pycode\":\n                yield from self.do_pyblock(s)\n\n            elif k == \"stm_os\":\n                yield from self.do_stmos(s)\n\n    # ------------------------------------------------------------------ #\n    # 内建函数\n    # ------------------------------------------------------------------ #\n    def do_call(self, s):\n        \"\"\"执行一条函数调用语句（S.xxx / R.xxx / STM.xxx / stmg.xxx）。\n\n        s 是 parser 解析出的 call 语句：obj 是点号前的对象（S/R/STM/STMG），\n        method 是方法名（已统一成下划线版本），args/kwargs 是实参。\n        这里按 (obj, method) 分派，把每类内建函数翻译成一或多个事件 yield 出去；\n        认不出的就 yield 一条「还没实现」的 toast 提示（不崩）。\n        \"\"\"\n        obj = (s[\"obj\"] or \"\").upper()\n        if obj == \"STMG\":                 # 剧本里 stmg.python(...) 和 STM.python(...) 等价\n            obj = \"STM\"\n        method = s[\"method\"].lower()\n        args, kw = s[\"args\"], s[\"kwargs\"]\n        a0 = args[0] if args else \"\"\n\n        # 成就解锁：STM.achieve(\"名称\") 与 ACHIEVE(\"名称\") 都走这里。\n        # 只有「第一次解锁」才产生事件，gui 据此弹窗；已解锁的静默跳过。\n        if method == \"achieve\":\n            # a0 已由解析器去掉引号，就是干净的成就名（字符串字面量直接可用）；\n            # 非字符串（如数字）也转成字符串，空值忽略。\n            name = a0 if isinstance(a0, str) else (\"\" if a0 is None else str(a0))\n            if name:\n                if name not in self.unlocked:\n                    self.unlocked.add(name)\n                    savemod.save_achievements(self.root, self.script.title,\n                                             self.unlocked)\n                    yield {\"t\": \"achieve\", \"name\": name, \"is_new\": True}\n                else:\n                    yield {\"t\": \"achieve\", \"name\": name, \"is_new\": False}\n            return\n\n        if obj == \"S\":\n            if method == \"character\" and a0:          # 兜底，正常走不到\n                yield from self._sprite_event(a0, args, kw)\n            elif method in (\"cg\", \"bg\", \"background\"):\n                # 和 Ren'Py 的 scene 一样：换背景会先把立绘清空\n                p = self.resolve(a0)\n                self._unlock_cg(p)\n                ev = {\"t\": \"bg\", \"path\": p, \"clear\": True}\n                d = self._dur(kw)\n                if d is not None:\n                    ev[\"dur\"] = d\n                yield ev\n            elif method == \"picture\":\n                p = self.resolve(a0)\n                self._unlock_cg(p)\n                ev = {\"t\": \"picture\", \"path\": p}\n                d = self._dur(kw)\n                if d is not None:\n                    ev[\"dur\"] = d\n                yield ev\n            elif method == \"play\":\n                loop = str(kw.get(\"loop\", \"true\")).lower() not in (\"false\", \"0\", \"no\")\n                # 路径含逗号 -> 拆成多首依次播放（S.play(\"a.mp3,b.mp3\")）；\n                # 只拆出一个就和老行为一致，和 T5 的 apply 幂等。\n                if \",\" in a0:\n                    for pp in a0.split(\",\"):\n                        pp = pp.strip()\n                        if pp:\n                            yield {\"t\": \"bgm\", \"path\": self.resolve(pp), \"loop\": loop}\n                else:\n                    yield {\"t\": \"bgm\", \"path\": self.resolve(a0), \"loop\": loop}\n            elif method == \"sound\":\n                yield {\"t\": \"se\", \"path\": self.resolve(a0)}\n            elif method == \"voice\":\n                yield {\"t\": \"voice\", \"path\": self.resolve(a0)}\n            elif method == \"stop\":\n                yield {\"t\": \"stop\", \"what\": (a0 or \"bgm\").lower()}\n            elif method == \"hide\":\n                yield {\"t\": \"hide\", \"what\": (a0 or \"sprite\").lower()}\n            elif method == \"transition\":\n                # 转场：gui 会拿它做全屏遮罩动画（fade / dissolve / flash），\n                # 在「上一帧」和「下一帧」之间切换；没写 S.transition 时完全不影响。\n                yield {\"t\": \"transition\", \"kind\": (a0 or \"fade\"),\n                       \"dur\": float(kw.get(\"dur\", \"0.4\"))}\n            elif method == \"avg_button\":\n                # ---- AVG 绘图（第 3 期）：S.AVG-button(x, y, \"形状\") ----\n                # 两种坐标写法都认（解析器已把 x:0 归一成 kwargs[\"x\"]）：\n                #   S.AVG-button(x:100, y:50, \"box\")   ← 冒号写法，形状在第 1 个位置参数\n                #   S.AVG-button(100, 50, \"box\")       ← 按顺序写，形状在第 3 个\n                # 坐标可以是算式/变量（SET 好感度 = 50 之后写 x:好感度*10 也行），\n                # 所以统一走 eval_expr 求值。\n                has_xy = \"x\" in kw or \"y\" in kw\n                xs = kw[\"x\"] if \"x\" in kw else (args[0] if not has_xy and args else 0)\n                ys = kw[\"y\"] if \"y\" in kw else (args[1] if not has_xy and len(args) > 1 else 0)\n                if has_xy:\n                    shape = kw.get(\"shape\") or (args[0] if args else \"\")\n                else:\n                    shape = args[2] if len(args) > 2 else kw.get(\"shape\", \"\")\n                shape = str(shape or \"\").strip()\n                try:\n                    x = float(self.eval_expr(str(xs)))\n                    y = float(self.eval_expr(str(ys)))\n                except STMFatal:\n                    x = y = 0.0        # 坐标算不出来就画在正中间，别让游戏崩\n                item = {\"t\": \"avg\", \"action\": \"draw\", \"shape\": shape,\n                        \"x\": x, \"y\": y}\n                # 可选参数：颜色 / 大小 / 线宽。写了才带上（没写渲染层用默认值）。\n                if kw.get(\"color\"):\n                    item[\"color\"] = str(kw[\"color\"])\n                if kw.get(\"size\") is not None:\n                    try:\n                        item[\"size\"] = float(self.eval_expr(str(kw[\"size\"])))\n                    except STMFatal:\n                        pass\n                if kw.get(\"width\") is not None:\n                    try:\n                        item[\"width\"] = max(1, int(float(self.eval_expr(str(kw[\"width\"])))))\n                    except STMFatal:\n                        pass\n                # 用户自定义形状：把 SET 定义的绘图指令塞进事件，\n                # 渲染层（pygame / canvas）拿它现算几何——事件自带全部信息，\n                # 网页版不用回头问 Python 引擎要数据。\n                if shape.lower() not in avg.PRIMITIVES:\n                    ops = self.avg_shapes.get(shape)\n                    if ops is None:\n                        # 谁都不认识的名字：开发模式下提示一句，发布版静默跳过\n                        if self.dev_mode:\n                            yield {\"t\": \"toast\",\n                                   \"text\": 'S.AVG-button: 形状「%s」没有 SET 定义过，已跳过' % shape}\n                        return\n                    item[\"ops\"] = ops\n                yield item\n            elif method == \"avg_clear\":\n                # S.AVG-clear()：把 AVG 画的所有东西一次擦干净\n                yield {\"t\": \"avg\", \"action\": \"clear\"}\n            elif method == \"jump\":\n                if a0 in self._labels:\n                    raise JumpSignal(self._labels[a0] + 1)\n                raise STMFatal('S.jump(\"%s\") 找不到这个标签' % a0)\n            elif method == \"end\":\n                raise JumpSignal(len(self.script.body))\n            else:\n                yield {\"t\": \"toast\", \"text\": \"S.%s 这个函数还没实现\" % s[\"method\"]}\n\n        elif obj == \"STM\":\n            if method == \"display\":\n                yield {\"t\": \"toast\", \"text\": a0}\n            elif method == \"python\":\n                # stmg.python(\"math\") 声明后面 python 代码块能用的库；\n                # stmg.python(\"none\") 表示不需要库，也是合法的。\n                ok, why = stdlib_api.check_library(a0)\n                if not ok:\n                    raise STMFatal(\"STM.python: \" + why)\n                if not self.dev_mode:\n                    yield {\"t\": \"toast\",\n                           \"text\": \"发布版不允许 STM.python(%s)，已忽略\" % a0}\n                else:\n                    for name, mod in stdlib_api.load_libraries(a0).items():\n                        if name in stdlib_api.RELEASE_BLOCKED:\n                            yield {\"t\": \"toast\",\n                                   \"text\": \"STM.python(%s) 被标记为仅开发模式可用\" % name}\n                            continue\n                        self._libraries[name] = True\n                        self._lib_modules[name] = mod\n                        yield {\"t\": \"python\", \"name\": name}\n            else:\n                yield {\"t\": \"toast\", \"text\": \"STM.%s 这个函数还没实现\" % s[\"method\"]}\n\n        elif obj == \"R\":\n            if method == \"api\":\n                key = kw.get(\"key\", \"\")\n                if key == \"option\":\n                    key = self.options.get(\"enc\", \"\") if self.options else \"\"\n                if not self.dev_mode and not self.options.get(\"allow_net\", True):\n                    yield {\"t\": \"toast\", \"text\": \"发布版已关闭联网，R.api 被忽略\"}\n                    return\n                # 回放：有对应 api 记录就短路，不真发请求（老存档没有则现场真执行）\n                rec = self._take_record(\"api\")\n                if rec is not None:\n                    result = rec.get(\"result\")\n                    self.STM.API = result\n                    self.vars[\"R\"].RESULT = result\n                    yield {\"t\": \"api_result\", \"ok\": bool(rec.get(\"ok\", False)),\n                           \"result\": result, \"n\": rec.get(\"n\", 0)}\n                    return\n                ok, result = stdlib_api.call_api(kw.get(\"url\", a0), key=key)\n                self.STM.API = result\n                self.vars[\"R\"].RESULT = result\n                self._api_n += 1\n                # 记进 answers 流，存档重放时就能短路、不重发请求\n                self.answers.append((\"api\", {\"url\": kw.get(\"url\", a0), \"key\": key,\n                                             \"ok\": ok, \"result\": result,\n                                             \"n\": self._api_n}))\n                yield {\"t\": \"toast\",\n                       \"text\": \"R.api %s：%s\" % (\"成功\" if ok else \"失败\",\n                                                str(result)[:60])}\n            else:\n                yield {\"t\": \"toast\", \"text\": \"R.%s 这个函数还没实现\" % s[\"method\"]}\n        else:\n            yield {\"t\": \"toast\", \"text\": \"不认识的调用：%s\" % s[\"method\"]}\n\n    def do_stmos(self, s):\n        \"\"\"stm.os 受控文件操作。设计上**静默**——发布版不弹任何提示，\n        这样在玩家机器上做 DDLC 式演出时才不会「穿帮」；只有开发模式\n        会把失败原因用 toast 打出来方便调试。\"\"\"\n        op = (s.get(\"op\") or \"\").lower()\n        path = (s.get(\"path\") or \"\").replace(\"\\\\\", \"/\")\n        if not path:\n            if self.dev_mode:\n                yield {\"t\": \"toast\", \"text\": \"stm.os: 没给路径\"}\n            return\n        # 绝对路径直接用；相对路径按项目根目录解析\n        p = path if os.path.isabs(path) else self.resolve(path)\n\n        # 回放：有对应 os 记录就短路，不真碰玩家磁盘（老存档没有则现场真执行）\n        rec = self._take_record(\"os\")\n        if rec is not None:\n            ok = bool(rec.get(\"ok\", False))\n            content = rec.get(\"content\", \"\")\n            if op == \"read\":\n                self.STM.OS = content\n                self.vars[\"STM.OS\"] = content\n            yield {\"t\": \"os_result\", \"ok\": ok, \"op\": op, \"path\": p,\n                   \"content\": content, \"n\": rec.get(\"n\", 0)}\n            return\n\n        if op == \"read\":\n            ok, content = stmos.read_file(p)\n            self.STM.OS = content if ok else \"\"\n            self.vars[\"STM.OS\"] = self.STM.OS\n            if not ok and self.dev_mode:\n                yield {\"t\": \"toast\", \"text\": \"stm.os read 失败：%s\" % p}\n            self._os_n += 1\n            self.answers.append((\"os\", {\"op\": op, \"path\": p, \"ok\": ok,\n                                        \"content\": content, \"n\": self._os_n}))\n            return\n\n        if op == \"create\":\n            ok, msg = stmos.create_file(p)\n            if not ok and self.dev_mode:\n                yield {\"t\": \"toast\", \"text\": \"stm.os create：%s\" % msg}\n            self._os_n += 1\n            self.answers.append((\"os\", {\"op\": op, \"path\": p, \"ok\": ok,\n                                        \"content\": \"\", \"n\": self._os_n}))\n            return\n\n        if op == \"remove\":\n            ok, msg = stmos.remove_file(p)\n            if not ok and self.dev_mode:\n                yield {\"t\": \"toast\", \"text\": \"stm.os remove：%s\" % msg}\n            self._os_n += 1\n            self.answers.append((\"os\", {\"op\": op, \"path\": p, \"ok\": ok,\n                                        \"content\": \"\", \"n\": self._os_n}))\n            return\n\n        if op == \"revision\":\n            ok, msg = stmos.revision_file(p, s.get(\"find\"), s.get(\"replace\"))\n            if not ok and self.dev_mode:\n                yield {\"t\": \"toast\", \"text\": \"stm.os revision：%s\" % msg}\n            self._os_n += 1\n            self.answers.append((\"os\", {\"op\": op, \"path\": p, \"ok\": ok,\n                                        \"content\": \"\", \"n\": self._os_n}))\n            return\n\n    def do_pyblock(self, s):\n        \"\"\"执行内嵌的 python 代码块。\n\n        代码里 print 出来的东西会一行一条地飘到右上角（toast），\n        行与行之间隔 delay 秒（默认 3 秒，写成 `python: 2` 就是 2 秒）。\n\n        立场和 STM.python 一致：**开发模式专属**、只能碰白名单库、\n        发布版整块跳过。所以它适合做调试输出 / 算点东西，\n        不适合当玩家看得见的正式功能。\n        \"\"\"\n        if not self.dev_mode:\n            yield {\"t\": \"toast\", \"text\": \"发布版不允许 python 代码块，已忽略\"}\n            return\n\n        src = \"\\n\".join(s.get(\"code\") or [])\n        if not src.strip():\n            return\n\n        try:\n            delay = max(0.0, float(s.get(\"delay\", PY_DELAY_DEFAULT)))\n        except (TypeError, ValueError):\n            delay = PY_DELAY_DEFAULT\n\n        first = s.get(\"code_line\") or ((s.get(\"line\") or 0) + 1)\n        fname = \"%s:行%d\" % (os.path.basename(self.script.path or \"script.stm\"), first)\n        try:\n            code = compile(src, fname, \"exec\")\n        except SyntaxError as e:\n            raise STMFatal(\n                \"python 代码块第 %d 行（剧本第 %d 行）语法不对：%s\\n  %s\\n\"\n                '  提示：引号要用半角的 \" ，中文的 “ ” 会被当成语法错误'\n                % (e.lineno or 1, first + (e.lineno or 1) - 1, e.msg,\n                   (e.text or \"\").strip()))\n\n        env = self._py_env()\n        buf = io.StringIO()\n        try:\n            with contextlib.redirect_stdout(buf):\n                exec(code, env)\n        except Exception as e:                        # noqa: BLE001\n            raise STMFatal(\"python 代码块出错：%s: %s\" % (type(e).__name__, e))\n        self._py_export(env)\n\n        lines = [ln.rstrip() for ln in buf.getvalue().splitlines()]\n        lines = [ln for ln in lines if ln.strip()]\n        if not lines:\n            return\n        extra = max(0, len(lines) - PY_MAX_LINES)\n        lines = lines[:PY_MAX_LINES]\n\n        # 读档重放：代码照跑（后面的剧情可能要用它算出来的变量），\n        # 但提示和等待不再演一遍——不然一读档就卡在几秒钟的提示里。\n        if self.quiet:\n            return\n        for i, ln in enumerate(lines):\n            yield {\"t\": \"toast\", \"text\": ln}\n            if delay > 0 and i < len(lines) - 1:\n                yield {\"t\": \"wait\", \"dur\": delay}\n        if extra:\n            yield {\"t\": \"toast\", \"text\": \"…还有 %d 行没有显示出来\" % extra}\n\n    def _py_env(self):\n        \"\"\"python 代码块的运行环境。\n\n        `__builtins__` 必须显式塞进去：不塞的话 Python 会把**完整**的内建表\n        自动挂上，open / exec / eval 就全进来了。\n        \"\"\"\n        builtins = dict(SAFE_BUILTINS)\n        builtins.update(stdlib_api.python_builtins())\n        env = {\"__builtins__\": builtins}\n        for name, mod in self._lib_modules.items():\n            env[name] = mod          # stmg.python(\"math\") 声明过的，直接按名字用\n        env[\"STM\"] = self.STM\n        env[\"RAND\"] = RAND\n        return env\n\n    def _py_export(self, env):\n        \"\"\"把代码块里算出来的变量写回剧本，后面 `SET 结果 = 它` 就能读到。\n\n        只搬字符串 / 数字 / 布尔 / 由它们组成的列表字典；模块、函数、类不搬。\n        \"\"\"\n        keep = (str, int, float, bool, list, dict, tuple, type(None))\n        for key, val in env.items():\n            if not isinstance(key, str) or key.startswith(\"_\"):\n                continue\n            if key in (\"STM\", \"RAND\") or key in self._lib_modules:\n                continue\n            if isinstance(val, type):\n                continue\n            if isinstance(val, keep):\n                self.vars[key] = val\n\n    # ------------------------------------------------------------------ #\n    # 小工具\n    # ------------------------------------------------------------------ #\n    def _sprite_event(self, path, args, kwargs):\n        \"\"\"拆 S.character(\"图.png\", pos=\"left\", tag=\"kongjie\")。\n\n        立绘可以同时站好几张，靠 tag 认人、pos 决定站哪（left/center/right）。\n        不写 tag 就用图片文件名当 tag。\n        \"\"\"\n        pos = str(kwargs.get(\"pos\") or (args[1] if len(args) > 1 else \"center\"))\n        tag = kwargs.get(\"tag\") or \"\"\n        if not tag:\n            base = os.path.basename(path.replace(\"\\\\\", \"/\"))\n            tag = os.path.splitext(base)[0]\n        ev = {\"t\": \"sprite\", \"path\": self.resolve(path),\n              \"pos\": pos.lower(), \"tag\": tag}\n        # 逐张立绘的增强控制：只有写了才带上，没写就走默认值（老脚本行为不变）。\n        # 剧本里写的是字面量，parser 给的是字符串，这里统一转成数字，免得渲染层再判断类型。\n        def _num(v, cast):\n            try:\n                return cast(v)\n            except (TypeError, ValueError):\n                return None\n        for key, cast in ((\"scale\", float), (\"alpha\", int),\n                          (\"y\", float), (\"rotate\", float)):\n            if key in kwargs and kwargs[key] is not None:\n                val = _num(kwargs[key], cast)\n                if val is not None:\n                    ev[key] = val\n        if \"expr\" in kwargs:\n            ev[\"expr\"] = kwargs[\"expr\"] or \"\"\n        # 补间时长：只有写了 dur= 才带上，没写就瞬切（老脚本行为不变）\n        d = self._dur(kwargs)\n        if d is not None:\n            ev[\"dur\"] = d\n        return [ev]\n\n    def _say_text(self, raw):\n        \"\"\"台词默认是纯文本；带 + 号或 STM. 的才当算式求值。\"\"\"\n        if \"+\" in raw or \"STM.\" in raw:\n            try:\n                return str(self.eval_expr(raw))\n            except STMFatal:\n                pass\n        return strip_quotes(raw)\n\n    def _assign(self, name, value):\n        if name.upper().startswith(\"STM.\"):\n            setattr(self.STM, name.split(\".\", 1)[1], value)\n            return\n        self.vars[name] = value\n\n    def _rand_draw(self, a, b):\n        \"\"\"回放感知随机：正常跑抽一枚记下，回放时吃记录原样返回。\n\n        与 _take_answer 共用同一条有序回放流 self._replay：choose/question\n        由 _take_answer 消费，rand 由本函数消费，二者按剧本里出现的顺序各取所需。\n        老存档里没有 rand 项时，下一项必然不是 (\"rand\", ..)，于是退回「现场新抽」，\n        不会越界吞噬 choose/question —— 旧存档依旧能正常重载（只是随机分支不再精确）。\n        \"\"\"\n        a, b = int(a), int(b)\n        if self._replay_i < len(self._replay):\n            kind, val = self._replay[self._replay_i]\n            if kind == \"rand\":\n                self._replay_i += 1\n                self.answers.append((\"rand\", val))\n                return val\n        val = random.randint(a, b)\n        self.answers.append((\"rand\", val))\n        return val\n\n    def _take_answer(self):\n        if self._replay_i < len(self._replay):\n            kind, val = self._replay[self._replay_i]\n            self._replay_i += 1\n            self.answers.append((kind, val))\n            return val\n        return None\n\n    def _take_record(self, kind):\n        \"\"\"从回放流里按类型取一条记录（R.api / stm.os 用）。\n\n        命中返回记录字典并推进回放指针（重放出的新存档里仍含这条，可继续重放）；\n        不命中（当前记录是别的类型，或流已读完）返回 None，表示要「现场真执行」。\n        老存档里没有 api/os 记录时，这里必然不命中，于是退回真执行、\n        **不会越界吞掉后面的 choose/question 记录**——和 _rand_draw 同款兼容写法。\n        \"\"\"\n        if self._replay_i < len(self._replay):\n            k, val = self._replay[self._replay_i]\n            if k == kind:\n                self._replay_i += 1\n                self.answers.append((k, val))\n                return val\n        return None\n\n    def _auto_voice(self, who):\n        \"\"\"语音自动挂载：有角色名且 AutoVoice 打开时，按命名约定找配音文件。\n\n        命名约定（按顺序尝试，命中即播，找不到静默跳过，不许报错）：\n            voice/<角色名>/<该角色第几句 4 位补零>.wav|.ogg|.mp3\n            voice/<角色名>/<全局台词序号 4 位补零>.wav|.ogg|.mp3\n        quiet（读档重放）时不产出，避免读档疯狂播配音。\n        产出的事件带 auto=True、tag=角色名，供「重听」定位。\n        \"\"\"\n        if self.quiet:\n            return\n        if not who:\n            return\n        if not self.options or not self.options.get(\"autovoice\"):\n            return\n        self._say_global_count += 1\n        self._say_char_count[who] = self._say_char_count.get(who, 0) + 1\n        vdir = (self.options.get(\"voicedir\") or \"voice\").replace(\"\\\\\", \"/\")\n        idx_char = self._say_char_count[who]\n        idx_global = self._say_global_count\n        exts = (\".wav\", \".ogg\", \".mp3\")\n        for idx in (idx_char, idx_global):\n            for ext in exts:\n                cand = os.path.join(self.root, vdir, who, \"%04d%s\" % (idx, ext))\n                if os.path.isfile(cand):\n                    yield {\"t\": \"voice\", \"path\": cand, \"auto\": True, \"tag\": who}\n                    return\n\n    def _dur(self, kw):\n        \"\"\"从 kwargs 里取补间时长 dur（秒），取不到或写错就返回 None（老行为）。\"\"\"\n        if \"dur\" in kw and kw[\"dur\"] is not None:\n            try:\n                return float(kw[\"dur\"])\n            except (TypeError, ValueError):\n                return None\n        return None\n\n    def _unlock_cg(self, path):\n        \"\"\"登记看过的 CG（背景 / 叠图），首次见到就落盘。\n\n        只记存在的真实图片；占位路径（文件不在）不进回廊，免得画廊里全是占位块。\n        \"\"\"\n        if not path:\n            return\n        # 占位路径（文件不存在、也不是资源包里的）不进回廊，免得画廊全是占位块\n        if not os.path.isfile(path) and not path.startswith(pack.PREFIX):\n            return\n        if path in self.seen_cg:\n            return\n        self.seen_cg.add(path)\n        savemod.save_cg(self.root, self.script.title, self.seen_cg)\n","/stmg_root/stmg/pack.py":"# -*- coding: utf-8 -*-\n\"\"\"发布版的资源容器 `assets.stmdec`。\n\n结构（加密之前的样子）：\n\n    4 字节   头部 JSON 的长度（大端）\n    N 字节   JSON：{\"files\": {\"music/bgm.mp3\": {\"o\": 偏移, \"n\": 长度}, ...}}\n    余下     所有文件内容顺序拼在一起\n\n整块再用 crypto.encrypt 加密。加载时一次性读进内存，之后按名字取字节流。\n\"\"\"\n\nimport hashlib\nimport io\nimport json\nimport os\nimport struct\n\nfrom . import crypto\n\n# 资源包内文件的虚拟路径前缀。剧本/界面里写 \"stmgpack:/music/bgm.mp3\" 时，\n# 走下面 open_binary/exists 的统一入口去打包后的资源里取，而不是去真实磁盘找。\nPREFIX = \"stmgpack:/\"\n\n_current = None\n# 补丁包：发布后下发的增量包（patch.stmdec）。存在时，open_binary / exists 优先用补丁，\n# 没有补丁包时行为和老版本完全一致。\n_patch = None\n_patch_deleted = set()\n\n\ndef set_current(pack):\n    global _current\n    _current = pack\n\n\ndef active():\n    return _current\n\n\ndef set_patch(pk):\n    global _patch\n    _patch = pk\n\n\ndef active_patch():\n    return _patch\n\n\ndef set_patch_deleted(items):\n    global _patch_deleted\n    _patch_deleted = set(items or [])\n\n\ndef clear_patch():\n    global _patch, _patch_deleted\n    _patch = None\n    _patch_deleted = set()\n\n\ndef apply_patch(root, key):\n    \"\"\"游戏启动时调用：若发布目录里存在补丁包（patch.stmdec / patch.json），\n    就加载它，使资源读取优先走补丁。两者都不存在时等于什么都没做。\"\"\"\n    stmdec = os.path.join(root, \"patch.stmdec\")\n    if os.path.isfile(stmdec):\n        try:\n            set_patch(AssetPack(stmdec, key))\n        except crypto.DecryptError:\n            # 口令不对或文件损坏：安全降级，退回主资源包\n            set_patch(None)\n    jf = os.path.join(root, \"patch.json\")\n    if os.path.isfile(jf):\n        try:\n            with open(jf, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n            set_patch_deleted(data.get(\"deleted\", []))\n        except (ValueError, OSError):\n            pass\n\n\ndef is_pack_path(path):\n    return isinstance(path, str) and path.startswith(PREFIX)\n\n\ndef rel_of(path):\n    return path[len(PREFIX):]\n\n\n# --------------------------------------------------------------------------- #\ndef _collect(root, patterns):\n    import fnmatch\n    out = []\n    for dirpath, _dirnames, filenames in os.walk(root):\n        for fn in filenames:\n            full = os.path.join(dirpath, fn)\n            rel = os.path.relpath(full, root).replace(\"\\\\\", \"/\")\n            if any(fnmatch.fnmatch(rel, p) or fnmatch.fnmatch(fn, p)\n                   for p in patterns):\n                out.append(rel)\n    out.sort()\n    return out\n\n\ndef _scan(root, patterns):\n    \"\"\"扫描 root 下匹配 patterns 的文件，返回 rel -> 原始字节。\"\"\"\n    names = [p for p in _collect(root, patterns)\n             if not p.endswith(\".stmdec\") and not p.startswith(\".stmg_save/\")]\n    data = {}\n    for rel in names:\n        with open(os.path.join(root, rel), \"rb\") as f:\n            data[rel] = f.read()\n    return data\n\n\ndef build(root, patterns, out_path, key):\n    \"\"\"把 root 下匹配 patterns 的文件打包加密到 out_path。返回打包了几个文件。\n\n    索引里每个资源都会记录 sha256（前 16 位够用）与 size；\n    老版本产出的「无 hash 索引」资源包也能被 AssetPack 正常读取（向后兼容）。\n    \"\"\"\n    return build_from_mapping(_scan(root, patterns), out_path, key)\n\n\ndef build_from_mapping(data, out_path, key):\n    \"\"\"从 {rel: 字节} 直接构建加密资源包（补丁工具复用同一套格式与密钥）。\n\n    产物 = [4字节大端头长][JSON 索引][所有文件内容顺序拼接]，整块再加密。\n    索引里每个资源记录 o(偏移)/n(长度)/hash(sha256 前16位)/size，\n    老版本「无 hash 索引」也能被 AssetPack 读（向后兼容）。\n    \"\"\"\n    index, blob, off = {}, bytearray(), 0\n    # 按 rel 排序，保证每次打出来的字节顺序稳定（补丁/校验可比）\n    for rel in sorted(data):\n        d = data[rel]\n        index[rel] = {\"o\": off, \"n\": len(d),\n                      \"hash\": hashlib.sha256(d).hexdigest()[:16],\n                      \"size\": len(d)}\n        blob.extend(d)\n        off += len(d)\n    # 索引写成 JSON（中文不转义，便于人读），再拼上文件正文\n    head = json.dumps({\"files\": index}, ensure_ascii=False).encode(\"utf-8\")\n    raw = struct.pack(\">I\", len(head)) + head + bytes(blob)\n    with open(out_path, \"wb\") as f:\n        # 整块加密：外部拿不到明文，也改不了单个文件\n        f.write(crypto.encrypt(raw, key))\n    return len(index), os.path.getsize(out_path)\n\n\n# --------------------------------------------------------------------------- #\nclass AssetPack(object):\n    def __init__(self, path, key):\n        self.path = path\n        self.index = {}\n        self.blob = b\"\"\n        with open(path, \"rb\") as f:\n            raw = crypto.decrypt(f.read(), key)\n        if len(raw) < 4:\n            raise crypto.DecryptError(\"资源包是空的\")\n        hlen = struct.unpack(\">I\", raw[:4])[0]\n        head = json.loads(raw[4:4 + hlen].decode(\"utf-8\"))\n        self.index = head.get(\"files\", {})\n        self.blob = raw[4 + hlen:]\n\n    def has(self, rel):\n        \"\"\"资源包里有没有这个 rel（不含补丁逻辑，只看主包索引）。\"\"\"\n        return rel in self.index\n\n    def read(self, rel):\n        \"\"\"按 rel 取出原始字节；没有这个资源抛 KeyError（调用方负责兜底）。\"\"\"\n        item = self.index.get(rel)\n        if not item:\n            raise KeyError(rel)\n        # 用索引里的偏移/长度从 blob 里切一段\n        return self.blob[item[\"o\"]:item[\"o\"] + item[\"n\"]]\n\n    @property\n    def names(self):\n        return sorted(self.index.keys())\n\n    def __len__(self):\n        return len(self.index)\n\n\n# --------------------------------------------------------------------------- #\ndef open_binary(path):\n    \"\"\"统一入口：真实文件 和 stmgpack:/... 都返回一个二进制文件对象。\n\n    存在补丁包时，补丁里的资源优先；被补丁标记为删除的资源会直接报错；\n    其余回退到主资源包。没有补丁包时行为与老版本完全一致。\n    \"\"\"\n    if is_pack_path(path):\n        if _current is None and _patch is None:\n            raise IOError(\"资源包没有加载\")\n        rel = rel_of(path)\n        if _patch is not None and _patch.has(rel):\n            return io.BytesIO(_patch.read(rel))\n        if rel in _patch_deleted:\n            raise IOError(\"资源已被补丁删除：%s\" % rel)\n        if _current is None:\n            raise IOError(\"资源包没有加载：%s\" % rel)\n        return io.BytesIO(_current.read(rel))\n    return open(path, \"rb\")\n\n\ndef exists(path):\n    if not path:\n        return False\n    if is_pack_path(path):\n        rel = rel_of(path)\n        if _patch is not None and _patch.has(rel):\n            return True\n        if rel in _patch_deleted:\n            return False\n        return _current is not None and _current.has(rel)\n    return os.path.isfile(path)\n","/stmg_root/stmg/crypto.py":"# -*- coding: utf-8 -*-\n\"\"\"`.stmdec` 加解密（纯标准库，零额外依赖）。\n\n文件格式：\n\n    偏移   长度   内容\n    0      4      magic  b\"STMG\"\n    4      1      版本号\n    5      16     salt\n    21     16     nonce\n    37     N      密文\n    37+N   32     HMAC-SHA256 校验值\n\n密钥派生：PBKDF2-HMAC-SHA256(password, salt, 120000) -> 32 字节\n密钥流  ：HMAC-SHA256(key, nonce || counter) 拼接后与明文异或\n校验    ：HMAC-SHA256(mac_key, 前面所有字节)\n\n⚠️ 说清楚：这不是强加密。\n密钥和密文是一起发布给玩家的，愿意花时间的人一定能解开。\n它的作用是「让玩家双击打不开、随手改不了」，**别拿它保护真密钥**。\n\"\"\"\n\nimport hashlib\nimport hmac\nimport os\nimport secrets\n\nMAGIC = b\"STMG\"\nVERSION = 1\nSALT_LEN = 16\nNONCE_LEN = 16\nMAC_LEN = 32\nROUNDS = 120000\nHEADER_LEN = len(MAGIC) + 1 + SALT_LEN + NONCE_LEN\n\n\nclass DecryptError(Exception):\n    \"\"\"解密失败统一抛这个（文件不是 .stmdec / 版本不对 / 密钥错 / 被人改过）。\"\"\"\n    pass\n\n\ndef _derive(password, salt, tag=b\"enc\"):\n    \"\"\"从同一个 password + salt 派生出一个 32 字节子密钥。\n\n    tag 用来区分用途：b\"enc\" 派出来当加密密钥，b\"mac\" 派出来当校验密钥。\n    两份子密钥彼此独立——即使把密文 XOR 出来也推导不出 MAC 密钥，反之亦然。\n    120000 轮 PBKDF2 纯粹为了提高暴力破解的成本（见文件头 ROUNDS）。\n    \"\"\"\n    return hashlib.pbkdf2_hmac(\n        \"sha256\", password.encode(\"utf-8\"), salt + tag, ROUNDS, dklen=32)\n\n\ndef _keystream(key, nonce, length):\n    \"\"\"造一段任意长度的「密钥流」——这就是整个加解密的核心。\n\n    做法：以 key 为 HMAC 密钥，nonce 拼上递增的计数 counter 反复算\n    HMAC-SHA256，把一个个 32 字节摘要首尾接起来，截到需要的长度。\n    同一个 (key, nonce) 每次算出来都一模一样（所以解密端能还原），\n    但内容对不知道 key 的人来说就是真随机噪声。明文和它逐字节 XOR 即加密。\n    \"\"\"\n    out = bytearray()\n    counter = 0\n    while len(out) < length:\n        out.extend(hmac.new(key, nonce + counter.to_bytes(8, \"big\"),\n                            hashlib.sha256).digest())\n        counter += 1\n    return bytes(out[:length])\n\n\ndef encrypt(plain, password):\n    \"\"\"把明文 plain（str 或 bytes）加密，返回完整的 .stmdec 字节包。\n\n    每次都重新随机生成 salt 和 nonce——这样同一句话用同一密码加密，\n    两次出来的字节也完全不同，别人没法靠「相同密文」推断「相同明文」。\n    \"\"\"\n    if isinstance(plain, str):\n        plain = plain.encode(\"utf-8\")\n    salt = secrets.token_bytes(SALT_LEN)       # 每次随机：抗重放/抗比对\n    nonce = secrets.token_bytes(NONCE_LEN)\n    key = _derive(password, salt, b\"enc\")\n    mac_key = _derive(password, salt, b\"mac\")\n    ct = bytes(a ^ b for a, b in zip(plain, _keystream(key, nonce, len(plain))))\n    head = MAGIC + bytes([VERSION]) + salt + nonce + ct\n    # 把「前面所有字节」的 HMAC 附在尾巴上，解密时用来验证密钥对 + 没被篡改\n    return head + hmac.new(mac_key, head, hashlib.sha256).digest()\n\n\ndef decrypt(blob, password):\n    \"\"\"解密 .stmdec 字节包，返回明文 bytes。\n\n    任何一道防线没过都抛 DecryptError：文件太短 / 魔数不对 / 版本不认 /\n    密钥错导致 HMAC 校验失败（这里也覆盖「文件被改过」的情况）。\n    \"\"\"\n    if len(blob) < HEADER_LEN + MAC_LEN:\n        raise DecryptError(\"文件太短，不像是 .stmdec\")\n    if blob[:4] != MAGIC:\n        raise DecryptError(\"文件头不对，不是 STMG 的加密包\")\n    ver = blob[4]\n    if ver != VERSION:\n        raise DecryptError(\"加密包版本 %d，这个引擎只认识 %d\" % (ver, VERSION))\n    salt = blob[5:5 + SALT_LEN]\n    nonce = blob[5 + SALT_LEN:5 + SALT_LEN + NONCE_LEN]\n    body, mac = blob[:-MAC_LEN], blob[-MAC_LEN:]\n    mac_key = _derive(password, salt, b\"mac\")\n    # 用 compare_digest 做**常量时间**比较，避免时序侧信道泄露密钥信息\n    if not hmac.compare_digest(\n            hmac.new(mac_key, body, hashlib.sha256).digest(), mac):\n        raise DecryptError(\"校验失败：密钥不对，或者文件被人改过\")\n    key = _derive(password, salt, b\"enc\")\n    ct = body[HEADER_LEN:]\n    return bytes(a ^ b for a, b in zip(ct, _keystream(key, nonce, len(ct))))\n\n\ndef encrypt_file(src, dst, password):\n    \"\"\"把本地文件 src 加密写到 dst，返回 dst 的字节大小。\"\"\"\n    with open(src, \"rb\") as f:\n        data = f.read()\n    with open(dst, \"wb\") as f:\n        f.write(encrypt(data, password))\n    return os.path.getsize(dst)                # 给上层显示「加密后多大」\n\n\ndef decrypt_file(src, password):\n    \"\"\"读本地 .stmdec 文件并解密，返回明文 bytes。\"\"\"\n    with open(src, \"rb\") as f:\n        return decrypt(f.read(), password)\n\n\ndef is_encrypted(path):\n    \"\"\"快速判断 path 是不是 .stmdec——只看前 4 字节魔数。\n\n    读不到（文件不存在 / 没权限）一律当「不是加密包」返回 False，\n    交给上层按普通文件处理或报错。\n    \"\"\"\n    try:\n        with open(path, \"rb\") as f:\n            return f.read(4) == MAGIC\n    except OSError:\n        return False\n\n\ndef load_text(path, password=None, encoding=\"utf-8\"):\n    \"\"\"统一读剧本入口：路径是 .stmdec 就解密，否则当普通文本读。\n\n    encoding 默认 utf-8，且普通文本分支用 \"utf-8-sig\" 打开——\n    顺手吃掉 Windows 记事本爱加的 BOM 头，免得第一行多出一个看不见的 ﻿。\n    \"\"\"\n    if is_encrypted(path):\n        if not password:\n            raise DecryptError(\"%s 是加密包，但没有提供密钥\" % os.path.basename(path))\n        return decrypt_file(path, password).decode(encoding)\n    with open(path, \"r\", encoding=encoding + \"-sig\") as f:\n        return f.read()\n","/stmg_root/stmg/stdlib_api.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 暴露给剧本的内建能力：STM.python 白名单 + R.api 联网。\n\n安全立场（README 里也会写）：\n  * STM.python 只能加载白名单里的标准库，而且**只有开发模式能用**。\n  * R.api 默认 5 秒超时，失败返回空串，绝不让网络问题卡死剧情。\n\"\"\"\n\nimport importlib\nimport json\nimport re\nimport urllib.error\nimport urllib.parse\nimport urllib.request\n\n# 允许 STM.python 加载的库 —— 都是纯计算/玩具类，不碰文件系统和进程\nPYTHON_WHITELIST = {\n    \"math\", \"random\", \"time\", \"datetime\", \"json\", \"re\", \"itertools\",\n    \"functools\", \"collections\", \"statistics\", \"fractions\", \"decimal\",\n    \"textwrap\", \"string\", \"unicodedata\", \"colorsys\", \"turtle\", \"webbrowser\",\n}\n\n# 发布版里连这些也不给\nRELEASE_BLOCKED = {\"turtle\", \"webbrowser\"}\n\n# 「不需要库」的写法：stmg.python(\"none\")\nNO_LIB = {\"none\", \"no\", \"null\", \"无\", \"没有\", \"不需要\", \"-\"}\n\n# python 代码块额外给的内建函数：只管计算和打印，不碰文件 / 进程 / 网络\nPY_EXTRA_BUILTINS = (\n    \"print\", \"type\", \"isinstance\", \"tuple\", \"set\", \"frozenset\",\n    \"any\", \"all\", \"map\", \"filter\", \"pow\", \"reversed\", \"chr\", \"ord\",\n    \"divmod\", \"repr\", \"format\", \"getattr\", \"hasattr\", \"iter\", \"next\",\n    \"slice\", \"bytes\", \"bytearray\", \"complex\", \"hex\", \"oct\", \"bin\",\n    \"callable\", \"id\", \"hash\", \"dir\",\n)\n\nAPI_TIMEOUT = 5\n\n\nclass ApiError(Exception):\n    pass\n\n\ndef split_libraries(text):\n    \"\"\"把 \"math,random\" / \"math、random\" / \"none\" 拆成一串干净的库名。\"\"\"\n    parts = re.split(r\"[,，、;；\\s]+\", (text or \"\").strip())\n    return [p for p in parts if p and p.lower() not in NO_LIB]\n\n\ndef check_library(name):\n    \"\"\"检查 STM.python / stmg.python 想加载的库能不能用。返回 (ok, 原因)。\"\"\"\n    raw = (name or \"\").strip()\n    if not raw:\n        return False, \"STM.python 没写库名（不需要库就写 none）\"\n    if raw.lower() in NO_LIB:\n        # stmg.python(\"none\")：明确表示「这个脚本不需要额外库」\n        return True, \"\"\n    for clean in split_libraries(raw):\n        if not re.match(r\"^[A-Za-z_]\\w*$\", clean):\n            return False, \"库名不合法：%s\" % clean\n        if clean not in PYTHON_WHITELIST:\n            return False, \"「%s」不在白名单里。允许的有：%s\" % (\n                clean, \"、\".join(sorted(PYTHON_WHITELIST)))\n    return True, \"\"\n\n\ndef load_libraries(text):\n    \"\"\"按声明把白名单库 import 进来，返回 {名字: 模块}。加载不了就跳过。\"\"\"\n    mods = {}\n    for clean in split_libraries(text):\n        if clean not in PYTHON_WHITELIST:\n            continue\n        try:\n            mods[clean] = importlib.import_module(clean)\n        except Exception:                            # noqa: BLE001\n            pass\n    return mods\n\n\ndef guarded_import(name, globals=None, locals=None, fromlist=(), level=0):\n    \"\"\"python 代码块里的 import：只放白名单库进来，别的直接报错。\"\"\"\n    root = (name or \"\").split(\".\")[0]\n    if root not in PYTHON_WHITELIST:\n        raise ImportError(\n            \"python 代码块只能 import 白名单里的库：%s（这里是 %s）\"\n            % (\"、\".join(sorted(PYTHON_WHITELIST)), name))\n    return importlib.import_module(name)\n\n\ndef python_builtins():\n    \"\"\"python 代码块用的内建表：在 SAFE_BUILTINS 之上补 print / 受限 import。\"\"\"\n    import builtins\n    table = {n: getattr(builtins, n) for n in PY_EXTRA_BUILTINS}\n    table[\"__import__\"] = guarded_import\n    return table\n\n\ndef call_api(url, key=None, method=\"GET\", params=None, data=None):\n    \"\"\"R.api 联网能力的实现。统一返回 (ok, 结果) 二元组：\n\n        ok=True   拿到响应；结果可能是解析好的 dict/list（JSON），\n                  也可能还是原始文本（服务器没返回合法 JSON）。\n        ok=False  任何失败（没写 url / 超时 / HTTP 报错 / 连不上），\n                  结果是「人话原因」字符串，剧情端据此决定怎么兜底。\n\n    key 作为 Bearer Token 放进 Authorization 头；params 拼到查询串；\n    data 非 None 时按 JSON 请求体发出，头标 Content-Type: application/json。\n    \"\"\"\n    if not url:\n        return False, \"R.api 没写 url\"\n    if not re.match(r\"^https?://\", url, re.I):\n        url = \"http://\" + url          # 用户偷懒没写协议：默认补 http\n\n    if params:\n        url += (\"&\" if \"?\" in url else \"?\") + urllib.parse.urlencode(params)\n\n    headers = {\"User-Agent\": \"STMG/1.0\"}\n    if key:\n        headers[\"Authorization\"] = \"Bearer %s\" % key\n\n    body = None\n    if data is not None:\n        body = json.dumps(data, ensure_ascii=False).encode(\"utf-8\")\n        headers[\"Content-Type\"] = \"application/json\"\n\n    req = urllib.request.Request(url, data=body, headers=headers,\n                                 method=method.upper())\n    # 安全底线：所有网络异常（超时 / 连不上 / 解析错）都吞掉，转成\n    # (False, 人话原因) 返回。绝不让一次 R.api 把整个剧情卡死——\n    # 联网是「锦上添花」，不是「没它玩不了」。\n    try:\n        with urllib.request.urlopen(req, timeout=API_TIMEOUT) as resp:\n            raw = resp.read()\n            text = raw.decode(\"utf-8\", \"replace\")\n    except urllib.error.HTTPError as e:\n        return False, \"HTTP %s %s\" % (e.code, e.reason)\n    except urllib.error.URLError as e:\n        return False, \"连不上：%s\" % e.reason\n    except Exception as e:                      # noqa: BLE001 - 网络层什么都可能抛\n        return False, \"请求失败：%s\" % e\n\n    try:\n        return True, json.loads(text)\n    except ValueError:\n        return True, text\n","/stmg_root/stmg/stmos.py":"# -*- coding: utf-8 -*-\n\"\"\"stm.os —— 受控的文件系统操作（DDLC 式彩蛋用）。\n\n只暴露 4 个动作，全部走「看起来像正常游戏功能」的接口，不暴露 Python\n运行时，避免在发布版里「穿帮」：\n\n    read     读文件，内容进 STM.OS\n    create   建一个空文件（已存在则不动）\n    remove   移到回收站（不是永久删除，能找回）\n    revision 改文件，先留 .bak 备份再替换\n\n安全兜底（这是和 STM.python 最大的区别，也是它能藏住的原因）：\n  * remove 永远走回收站，误删可找回，绝不做永久删除 / 递归删除。\n  * revision 永远先留 filename.后缀.bak，改坏了能还原。\n  * 不做格式化、不碰系统目录——这里只管「读 / 建 / 移回收站 / 改 + 备份」。\n\n注意：这本质是读写玩家机器上的文件。请只用于自己电脑上的演示，\n或玩家明确知情同意的演出（比如读写游戏自己的存档目录）。\n\"\"\"\n\nimport os\nimport shutil\nimport sys\n\n\n# --------------------------------------------------------------------------- #\n# 对外动作\n# --------------------------------------------------------------------------- #\ndef read_file(path):\n    \"\"\"读文件，返回 (ok, 内容字符串)。打不开返回 (False, \"\")。\"\"\"\n    try:\n        with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n            return True, f.read()\n    except Exception:\n        return False, \"\"\n\n\ndef create_file(path):\n    \"\"\"建一个空文件。已存在则不动，返回 (ok, 消息)。\"\"\"\n    try:\n        if os.path.exists(path):\n            return True, \"已存在，未改动\"\n        parent = os.path.dirname(path)\n        if parent and not os.path.isdir(parent):\n            os.makedirs(parent)\n        with open(path, \"w\", encoding=\"utf-8\") as f:\n            pass\n        return True, \"\"\n    except Exception as e:                       # noqa: BLE001\n        return False, \"%s: %s\" % (type(e).__name__, e)\n\n\ndef remove_file(path):\n    \"\"\"删文件，但**移进回收站**而不是永久删除。返回 (ok, 消息)。\"\"\"\n    if not os.path.exists(path):\n        return True, \"不存在，跳过\"\n    try:\n        if send_to_trash(path):\n            return True, \"\"\n        return False, \"移回收站失败\"\n    except Exception as e:                       # noqa: BLE001\n        return False, \"%s: %s\" % (type(e).__name__, e)\n\n\ndef revision_file(path, old, new):\n    \"\"\"改文件，先留 .bak 备份。返回 (ok, 消息)。\n\n    两种用法：\n      * old 非空：把文件里**所有** old 替换成 new（经典替换）\n      * old 为空：把**整个文件内容**直接设成 new（相当于写入 / 覆盖）\n    两种情况都会先复制一份 filename.后缀.bak。\n    \"\"\"\n    if old is None or new is None:\n        return False, \"revision 需要 ,\\\"旧内容\\\"to\\\"新内容\\\"\"\n    if not os.path.exists(path):\n        return False, \"文件不存在\"\n    try:\n        bak = path + \".bak\"\n        shutil.copy2(path, bak)\n        if old:\n            with open(path, \"r\", encoding=\"utf-8\", errors=\"replace\") as f:\n                data = f.read()\n            data = data.replace(old, new)\n        else:\n            data = new\n        with open(path, \"w\", encoding=\"utf-8\") as f:\n            f.write(data)\n        return True, \"\"\n    except Exception as e:                       # noqa: BLE001\n        return False, \"%s: %s\" % (type(e).__name__, e)\n\n\n# --------------------------------------------------------------------------- #\n# 回收站（跨平台）\n# --------------------------------------------------------------------------- #\ndef send_to_trash(path):\n    \"\"\"把文件 / 目录移到系统回收站。成功返回 True。\"\"\"\n    if sys.platform.startswith(\"win\"):\n        return _win_trash(path)\n    if sys.platform == \"darwin\":\n        return _mac_trash(path)\n    return _linux_trash(path)\n\n\ndef _win_trash(path):\n    \"\"\"Windows：用 SHFileOperationW 的 FO_DELETE + FOF_ALLOWUNDO 移进回收站。\"\"\"\n    try:\n        import ctypes\n        from ctypes import (Structure, byref, create_unicode_buffer,\n                            wintypes)\n    except Exception:                            # noqa: BLE001\n        return _fallback_trash(path)\n    try:\n        class SHFILEOPSTRUCTW(Structure):\n            _fields_ = [\n                (\"hwnd\", wintypes.HWND),\n                (\"wFunc\", wintypes.UINT),\n                (\"pFrom\", wintypes.LPCWSTR),\n                (\"pTo\", wintypes.LPCWSTR),\n                (\"fFlags\", wintypes.UINT),\n                (\"fAnyOperationsAborted\", wintypes.BOOL),\n                (\"hNameMappings\", wintypes.LPVOID),\n                (\"lpszProgressTitle\", wintypes.LPCWSTR),\n            ]\n\n        FO_DELETE = 3\n        FOF_ALLOWUNDO = 0x40        # 移回收站\n        FOF_NOCONFIRMATION = 0x10   # 不弹确认框\n        FOF_SILENT = 0x4\n        FOF_NOERRORUI = 0x400\n\n        # pFrom 需要双 null 结尾\n        src = create_unicode_buffer(path + \"\\0\\0\")\n        op = SHFILEOPSTRUCTW(\n            0, FO_DELETE, src, None,\n            FOF_ALLOWUNDO | FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI,\n            0, None, None)\n        res = ctypes.windll.shell32.SHFileOperationW(byref(op))\n        if res == 0 and not op.fAnyOperationsAborted:\n            return True\n        return _fallback_trash(path)\n    except Exception:                            # noqa: BLE001\n        return _fallback_trash(path)\n\n\ndef _mac_trash(path):\n    \"\"\"macOS：mv 到 ~/.Trash。\"\"\"\n    try:\n        trash = os.path.expanduser(\"~/.Trash\")\n        os.makedirs(trash, exist_ok=True)\n        dest = os.path.join(trash, os.path.basename(path))\n        if os.path.exists(dest):\n            dest += \".stm\"            # 回收站里已有同名：加 .stm 避开覆盖\n        shutil.move(path, dest)\n        return True\n    except Exception:                            # noqa: BLE001\n        return _fallback_trash(path)\n\n\ndef _linux_trash(path):\n    \"\"\"Linux：优先 gio trash，失败退回 ~/.local/share/Trash。\"\"\"\n    try:\n        import subprocess\n        subprocess.run([\"gio\", \"trash\", path], check=True,\n                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        return True\n    except Exception:                            # noqa: BLE001\n        try:\n            trash = os.path.join(os.path.expanduser(\"~\"),\n                                 \".local\", \"share\", \"Trash\", \"files\")\n            os.makedirs(trash, exist_ok=True)\n            dest = os.path.join(trash, os.path.basename(path))\n            if os.path.exists(dest):\n                dest += \".stm\"\n            shutil.move(path, dest)\n            return True\n        except Exception:                        # noqa: BLE001\n            return _fallback_trash(path)\n\n\ndef _fallback_trash(path):\n    \"\"\"兜底：移到用户目录下的 .stm_os_trash，绝不永久删除。\"\"\"\n    try:\n        box = os.path.join(os.path.expanduser(\"~\"), \".stm_os_trash\")\n        os.makedirs(box, exist_ok=True)\n        dest = os.path.join(box, os.path.basename(path))\n        if os.path.exists(dest):\n            dest += \".stm\"\n        if os.path.isdir(path):\n            shutil.copytree(path, dest)\n            shutil.rmtree(path, ignore_errors=True)\n        else:\n            shutil.move(path, dest)\n        return True\n    except Exception:                            # noqa: BLE001\n        return False\n","/stmg_root/stmg/options.py":"# -*- coding: utf-8 -*-\n\"\"\"options.stm 解析。\n\n设计稿里的样子：\n\n    <\n    About = \"这里是显示在 about 中的内容\"\n    Enc   = \"这里是密钥\"\n    dec   = \"*.stm,*.png,*.txt\"\n    Key   = \"132456789\"\n    >\n\n补充约定：\n  * `Enc`（或 `Key`）—— 加密 / 解密用的口令，两个都写时以 Enc 为准\n  * `dec`            —— 加密时打包哪些文件，逗号分隔的 glob\n  * `About`          —— 「关于」界面里显示的文字\n  * `AllowNet`       —— 发布版要不要允许 R.api 联网，默认 true\n\"\"\"\n\nimport os\nimport re\n\nfrom .errors import Issue\n\n\nDEFAULTS = {\n    \"about\": \"\",\n    \"enc\": \"\",\n    \"key\": \"\",\n    \"dec\": [],\n    \"allow_net\": True,\n    \"autovoice\": False,\n    \"voicedir\": \"voice\",\n}\n\n\ndef parse_options_text(text, path=\"<memory>\"):\n    opt = dict(DEFAULTS)\n    issues = []\n    # raw：先原样收集 <键, 值>，最后再统一映射到 opt（方便处理 Enc/Key 优先级等）\n    raw = {}\n    for n, line in enumerate(text.splitlines(), 1):\n        s = line.strip()\n        # 空行和区块括号（<  >  <\/>）直接跳过，不是配置项\n        if not s or s in (\"<\", \">\", \"<\/>\"):\n            continue\n        m = re.match(r\"^([A-Za-z_]\\w*)\\s*=\\s*(.*)$\", s)\n        if not m:\n            # 写歪了（不是「键 = 值」）记一笔，但不中断，其他项照常解析\n            issues.append(Issue(n, \"options 里这行看不懂：%s\" % s[:30]))\n            continue\n        # 键统一小写（About / about 等价）\n        k = m.group(1).lower()\n        v = m.group(2).strip()\n        # 值是被英文双引号包住的字符串字面量时，剥掉引号\n        if len(v) >= 2 and v[0] == '\"' and v[-1] == '\"':\n            v = v[1:-1]\n        raw[k] = v\n\n    opt[\"about\"] = raw.get(\"about\", \"\")\n    # 口令优先级：Enc 优先于 Key（两者都写时以 Enc 为准）；都没写就是空（不加密）\n    opt[\"enc\"] = raw.get(\"enc\", \"\") or raw.get(\"key\", \"\")\n    opt[\"key\"] = raw.get(\"key\", \"\")\n    if raw.get(\"dec\"):\n        # 写了 dec：按逗号拆成 glob 列表（去掉首尾空格和空项）\n        opt[\"dec\"] = [x.strip() for x in raw[\"dec\"].split(\",\") if x.strip()]\n    else:\n        # 没写 dec：给一套默认打包清单（剧本 + 常见素材类型）\n        opt[\"dec\"] = [\"*.stm\", \"*.png\", \"*.jpg\", \"*.mp3\", \"*.wav\", \"*.ogg\"]\n    # 是否允许 R.api 联网：默认 true；写 false/0/no 才关（大小写不限）\n    opt[\"allow_net\"] = raw.get(\"allownet\", \"true\").lower() not in (\"false\", \"0\", \"no\")\n    # 语音自动挂载：AutoVoice = \"true\" 时，有角色名的台词按命名约定自动找配音\n    opt[\"autovoice\"] = raw.get(\"autovoice\", \"false\").lower() in (\"true\", \"1\", \"yes\", \"是\")\n    # 配音目录：默认 voice；用户写空串时用兜底 \"voice\"\n    opt[\"voicedir\"] = raw.get(\"voicedir\", \"voice\").strip() or \"voice\"\n    opt[\"_raw\"] = raw\n    opt[\"_issues\"] = issues\n    return opt\n\n\ndef load_options(path, key=None):\n    \"\"\"读 options。`.stmdec`（加密版）要用口令解开才能读；读不了时退回默认值不崩。\"\"\"\n    # 路径为空或文件不存在：直接给默认配置（带空 issues 列表）\n    if not path or not os.path.isfile(path):\n        return dict(DEFAULTS, dec=list(DEFAULTS[\"dec\"]), _issues=[])\n    from . import crypto\n    try:\n        if crypto.is_encrypted(path):\n            # 加密文件：用口令解密出明文\n            text = crypto.load_text(path, key)\n        else:\n            # 普通文本：utf-8-sig 兼容带 BOM 的文件\n            with open(path, \"r\", encoding=\"utf-8-sig\") as f:\n                text = f.read()\n    except (crypto.DecryptError, OSError, UnicodeDecodeError) as e:\n        # 口令错 / 文件坏 / 编码不对：不中断游戏，退回默认并记下原因\n        return dict(DEFAULTS, dec=list(DEFAULTS[\"dec\"]),\n                    _issues=[Issue(None, \"options 读不了：%s\" % e)])\n    # 先剥掉 HTML 风格注释 <!-- ... -->（跨行），再交给解析器\n    text = re.sub(r\"<--.*?-->\", \"\", text, flags=re.S)\n    return parse_options_text(text, path)\n\n\ndef find_options(script_path):\n    \"\"\"在剧本同级找 options.stm / options.stmdec。\"\"\"\n    d = os.path.dirname(os.path.abspath(script_path))\n    for name in (\"options.stm\", \"options.stmdec\"):\n        p = os.path.join(d, name)\n        if os.path.isfile(p):\n            return p\n    return \"\"\n","/stmg_root/stmg/save.py":"# -*- coding: utf-8 -*-\n\"\"\"存档槽读写。\n\n存档不保存「引擎内部状态」，而是保存**玩家做过的所有选择** + 已经翻到第几句。\n读档时从头重放，重放到同一个断点停下。\n好处：不依赖 Runtime 的内部结构，改引擎也不会读不了老存档。\n\"\"\"\n\nimport json\nimport os\nimport re\nimport time\nimport zipfile\n\nSAVE_DIR = \".stmg_save\"\nSLOTS = 6\n\n# 缩略图文件后缀：delete_slot 时一并清理（图片内容由 T3 用 pygame 写入，这里只管路径）\nTHUMB_SUFFIX = \".thumb.png\"\n\n\ndef save_dir(root):\n    d = os.path.join(root, SAVE_DIR)\n    if not os.path.isdir(d):\n        os.makedirs(d, exist_ok=True)\n    return d\n\n\ndef slot_path(root, n):\n    return os.path.join(save_dir(root), \"slot%d.json\" % int(n))\n\n\ndef thumb_path(root, n):\n    \"\"\"<root>/.stmg_save/slot<N>.thumb.png —— 某个槽的缩略图绝对路径。\"\"\"\n    return os.path.join(save_dir(root), \"slot%d%s\" % (int(n), THUMB_SUFFIX))\n\n\ndef has_thumb(root, n):\n    \"\"\"该槽有没有缩略图。\"\"\"\n    return os.path.isfile(thumb_path(root, n))\n\n\ndef drop_thumb(root, n):\n    \"\"\"删掉该槽的缩略图（删档时一起调）。成功删除返回 True，没有 / 删失败返回 False。\"\"\"\n    p = thumb_path(root, n)\n    if os.path.isfile(p):\n        try:\n            os.remove(p)\n            return True\n        except OSError:\n            return False\n    return False\n\n\ndef write_slot(root, n, snap):\n    \"\"\"把一帧存档快照 snap 写进槽 n（覆盖）。返回的还是这份带 time 的快照。\"\"\"\n    snap = dict(snap)                       # 复制一份，别改了调用方传进来的 dict\n    snap[\"time\"] = time.strftime(\"%Y-%m-%d %H:%M\")   # 存档格子上显示的时间戳\n    with open(slot_path(root, n), \"w\", encoding=\"utf-8\") as f:\n        json.dump(snap, f, ensure_ascii=False, indent=1)\n    return snap\n\n\ndef read_slot(root, n):\n    \"\"\"读槽 n 的快照 dict；文件不存在 / 解析不出返回 None（上层当空槽处理）。\"\"\"\n    p = slot_path(root, n)\n    if not os.path.isfile(p):\n        return None\n    try:\n        with open(p, \"r\", encoding=\"utf-8\") as f:\n            return json.load(f)\n    except (ValueError, OSError):\n        return None\n\n\ndef list_slots(root):\n    out = []\n    for i in range(1, SLOTS + 1):\n        out.append(read_slot(root, i))\n    return out\n\n\ndef delete_slot(root, n):\n    p = slot_path(root, n)\n    ok = False\n    if os.path.isfile(p):\n        os.remove(p)\n        ok = True\n    # 顺手把缩略图也清掉，免得留个孤零零的 .thumb.png\n    drop_thumb(root, n)\n    return ok\n\n\ndef describe(snap):\n    \"\"\"读档界面里给一个槽生成一行简介：时间 + 最近一句台词/选择的前 18 字。\n\n    history_tail 是快照里存的最近若干步历史，每项是 [步类型, 文本] 这样的\n    二元组；取最后一条的文本当「你上次停在这儿」的预览。\n    \"\"\"\n    if not snap:\n        return \"空档\"\n    tail = snap.get(\"history_tail\") or []\n    snippet = \"\"\n    if tail:\n        snippet = tail[-1][1] if isinstance(tail[-1], (list, tuple)) else str(tail[-1])\n    snippet = snippet.replace(\"\\n\", \" \")[:18]      # 换行压成空格，截断避免超长\n    return \"%s  %s\" % (snap.get(\"time\", \"?\"), snippet)\n\n\n# --------------------------------------------------------------------------- #\n# 成就系统（跨会话持久化）\n# --------------------------------------------------------------------------- #\nACHIEVE_FILE = \"achievements.json\"\n\n\ndef load_achievements(root, title):\n    \"\"\"读某个剧本（按标题区分）已解锁的成就集合，读不到返回空集合。\n\n    root 是项目目录，成就存在 <root>/.stmg_save/achievements.json 里，\n    整体是个 {标题: [成就名...]} 的字典，所以可以一个存档目录容纳多款游戏。\n    \"\"\"\n    p = os.path.join(save_dir(root), ACHIEVE_FILE)\n    if not os.path.isfile(p):\n        return set()\n    try:\n        with open(p, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n    except (ValueError, OSError):\n        return set()\n    names = data.get(title, [])\n    return set(names) if isinstance(names, (list, tuple, set)) else set()\n\n\ndef save_achievements(root, title, names):\n    \"\"\"把某个剧本的已解锁成就集合写回 achievements.json。\"\"\"\n    d = save_dir(root)\n    p = os.path.join(d, ACHIEVE_FILE)\n    data = {}\n    if os.path.isfile(p):\n        try:\n            with open(p, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n        except (ValueError, OSError):\n            data = {}\n    if not isinstance(data, dict):\n        data = {}\n    data[title] = sorted(names)\n    try:\n        with open(p, \"w\", encoding=\"utf-8\") as f:\n            json.dump(data, f, ensure_ascii=False, indent=1)\n    except OSError:\n        pass\n\n\n# --------------------------------------------------------------------------- #\n# CG 回廊（看过的背景 / 叠图，跨会话持久化）\n# --------------------------------------------------------------------------- #\nCG_FILE = \"cg.json\"\n\n\ndef load_cg(root, title):\n    \"\"\"读某个剧本已解锁的 CG 路径集合，读不到返回空集合。\n\n    存在 <root>/.stmg_save/cg.json，结构和 achievements.json 一样：\n    {标题: [路径...]}，一个存档目录可以容纳多款游戏。\n    \"\"\"\n    p = os.path.join(save_dir(root), CG_FILE)\n    if not os.path.isfile(p):\n        return set()\n    try:\n        with open(p, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n    except (ValueError, OSError):\n        return set()\n    paths = data.get(title, [])\n    return set(paths) if isinstance(paths, (list, tuple, set)) else set()\n\n\ndef save_cg(root, title, paths):\n    \"\"\"把某个剧本已解锁的 CG 集合写回 cg.json。\"\"\"\n    d = save_dir(root)\n    p = os.path.join(d, CG_FILE)\n    data = {}\n    if os.path.isfile(p):\n        try:\n            with open(p, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n        except (ValueError, OSError):\n            data = {}\n    if not isinstance(data, dict):\n        data = {}\n    data[title] = sorted(paths)\n    try:\n        with open(p, \"w\", encoding=\"utf-8\") as f:\n            json.dump(data, f, ensure_ascii=False, indent=1)\n    except OSError:\n        pass\n\n\n# --------------------------------------------------------------------------- #\n# 语言偏好（多语言剧本：script.stm + script.<lang>.stm）\n# --------------------------------------------------------------------------- #\nLANG_FILE = \"lang.json\"\n\n\ndef load_lang(root, title):\n    \"\"\"读某个剧本上次选的语言（空串 = 默认版 script.stm）。\"\"\"\n    p = os.path.join(save_dir(root), LANG_FILE)\n    if not os.path.isfile(p):\n        return \"\"\n    try:\n        with open(p, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n    except (ValueError, OSError):\n        return \"\"\n    v = data.get(title, \"\") if isinstance(data, dict) else \"\"\n    return v if isinstance(v, str) else \"\"\n\n\ndef save_lang(root, title, lang):\n    \"\"\"记住某个剧本的语言选择。\"\"\"\n    d = save_dir(root)\n    p = os.path.join(d, LANG_FILE)\n    data = {}\n    if os.path.isfile(p):\n        try:\n            with open(p, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n        except (ValueError, OSError):\n            data = {}\n    if not isinstance(data, dict):\n        data = {}\n    data[title] = lang\n    try:\n        with open(p, \"w\", encoding=\"utf-8\") as f:\n            json.dump(data, f, ensure_ascii=False, indent=1)\n    except OSError:\n        pass\n\n\n# --------------------------------------------------------------------------- #\n# 存档导入 / 导出（#6）\n#\n# 单个存档包格式 .stmgsav：一个 zip，里面是\n#   manifest.json          {\"format\":1, \"title\":..., \"engine\":\"STMG\", \"count\":n}\n#   slot1.json ... slot6.json   只含非空槽（槽号与存档目录里的文件名一致）\n# 缩略图不进包（图片由 T3 运行时生成），导入导出只搬槽位的 JSON 数据。\n# --------------------------------------------------------------------------- #\nSLOT_FILE_RE = re.compile(r\"^slot(\\d+)\\.json$\")\n\n\ndef export_slots(root, title, out_path, slots=None):\n    \"\"\"把若干存档槽导出成一个 .stmgsav 包。\n\n    root     项目目录（存档在 <root>/.stmg_save）\n    title    游戏标题，写进 manifest\n    out_path 导出的 .stmgsav 完整路径\n    slots    None = 全部 6 个槽；否则给定槽号列表（如 [1,3]）\n\n    返回 (ok, 消息)。没有任何非空槽时返回 (False, 原因)。\n    \"\"\"\n    d = save_dir(root)\n    if slots is None:\n        candidates = list(range(1, SLOTS + 1))\n    else:\n        candidates = [int(x) for x in slots]\n    planned = {}\n    for n in candidates:\n        snap = read_slot(root, n)\n        if snap:                       # 空槽不进包\n            planned[n] = snap\n    if not planned:\n        return (False, \"没有可导出的存档（所有槽都是空的）\")\n    manifest = {\"format\": 1, \"title\": title, \"engine\": \"STMG\",\n                \"count\": len(planned)}\n    try:\n        with zipfile.ZipFile(out_path, \"w\", zipfile.ZIP_DEFLATED) as zf:\n            zf.writestr(\"manifest.json\",\n                        json.dumps(manifest, ensure_ascii=False, indent=1))\n            for n, snap in planned.items():\n                zf.writestr(\"slot%d.json\" % n,\n                            json.dumps(snap, ensure_ascii=False, indent=1))\n    except OSError as e:\n        return (False, \"导出失败：%s\" % e)\n    return (True, \"已导出 %d 个存档到 %s\" % (len(planned), out_path))\n\n\ndef import_slots(src_path, root, overwrite=True):\n    \"\"\"从 .stmgsav 导入存档槽。\n\n    导入前会做完整校验：不是 zip / 缺 manifest / 不是 STMG 存档 / 槽文件非法，\n    一律返回 (False, 原因, 0) 且**不写任何文件**（先在校验阶段把内容全读进内存）。\n    校验通过后才落盘。slot 已存在且 overwrite=False 时跳过并计数。\n\n    返回 (ok, 消息, 导入槽数)。\n    \"\"\"\n    if not os.path.isfile(src_path):\n        return (False, \"找不到存档文件：%s\" % src_path, 0)\n    # 1) 先试着当 zip 打开，打不开说明不是合法存档包\n    try:\n        zf = zipfile.ZipFile(src_path, \"r\")\n    except (zipfile.BadZipFile, OSError):\n        return (False, \"这不是合法的 STMG 存档包（zip 解不开）\", 0)\n    try:\n        names = zf.namelist()\n        # 2) 必须有 manifest.json，且是合法的 STMG 清单\n        if \"manifest.json\" not in names:\n            return (False, \"存档包缺少 manifest.json\", 0)\n        try:\n            manifest = json.loads(zf.read(\"manifest.json\").decode(\"utf-8\"))\n        except (ValueError, UnicodeDecodeError):\n            return (False, \"manifest.json 不是合法 JSON\", 0)\n        if not isinstance(manifest, dict) or manifest.get(\"engine\") != \"STMG\":\n            return (False, \"这不是 STMG 存档（engine 字段不符）\", 0)\n        # 3) 逐个槽文件：槽号必须在 1~SLOTS，且内容得是合法非空 JSON\n        planned = {}        # n -> 原始字节\n        for nm in names:\n            m = SLOT_FILE_RE.match(nm)\n            if not m:\n                continue\n            n = int(m.group(1))\n            if n < 1 or n > SLOTS:\n                continue\n            try:\n                raw = zf.read(nm)\n                data = json.loads(raw.decode(\"utf-8\"))\n            except (ValueError, UnicodeDecodeError):\n                return (False, \"槽位文件 %s 不是合法 JSON\" % nm, 0)\n            if not isinstance(data, dict) or not data:\n                continue    # 空槽不导入\n            planned[n] = raw\n    finally:\n        zf.close()\n\n    # 4) 校验全部通过，才真正落盘\n    imported = 0\n    for n, raw in planned.items():\n        target = slot_path(root, n)\n        if os.path.isfile(target) and not overwrite:\n            continue\n        try:\n            with open(target, \"wb\") as f:\n                f.write(raw)\n        except OSError as e:\n            return (False, \"写入存档失败（槽 %d）：%s\" % (n, e), imported)\n        imported += 1\n    return (True, \"成功导入 %d 个存档槽\" % imported, imported)\n","/stmg_root/stmg/web_bridge.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG 网页版引擎桥 —— 在 Pyodide（WebAssembly 里的 CPython）中跑**真正的引擎**。\n\n网页版的 JS 只负责画界面、收键盘；剧本的解析、变量求值、分支推进\n全部交给这个文件背后的 Python 引擎。所以网页版和桌面版跑的是同一套\n逻辑，不会出现「网页里这样、桌面上那样」的偏差。\n\n接口就一个类：\n\n    d = Driver(script_text, options_text)\n    d.next(None)        -> 一条事件的 JSON（say / choose / bg / sprite / bgm ...）\n    d.next(\"选项名\")     -> 把玩家的回答送回剧本，返回下一条事件\n    d.next(\"输入的文字\")  -> 同上（问玩家名字那种）\n    剧本跑完返回 {\"t\": \"__done__\"}\n\n事件类型和桌面版完全一致，见 stmg/runtime.py 顶部的说明。\n\n网页比桌面多出来的两件事，都在这个文件里兜住：\n\n**① R.api 的异步**（第 2 期 #12）\n    浏览器里没有「同步阻塞的 socket」，Python 侧又没法 await JS 的 fetch。\n    所以 R.api 走「挂起 → 交给 JS 去 fetch → 重建执行流接回去」：\n    引擎跑到 R.api 时不去发请求，而是抛一个 `_PendingAPI` 把请求冒泡出来，\n    `next()` 把它变成一条 `{\"t\": \"api_pending\"}` 事件交给页面；\n    页面 fetch 完调 `resolve_api()` 把结果塞进缓存，下一拍 Driver 重新\n    起一个生成器、把记下来的 `answers` 喂回去，重跑一遍，\n    走出和第一次一模一样的路，接在挂起点后面继续。\n\n    停在哪儿是用 **api 序号** 认的，不是数事件条数：同一个剧本「首轮」和\n    「重放」产出的事件数并不一样（`stm.os` 只在重放时才吐 `os_result`），\n    拿条数当进度迟早对不上，会漏事件甚至把台词放两遍。序号则一定对得上。\n    重跑本身是安全的：剧本里的选择 / 随机 / 文件操作都有 `answers` 记录，\n    重跑只重放结果、不再真的执行一遍（这也是存档重放用的同一套机制）。\n\n**② stm.os 的沙箱虚拟文件系统**（第 2 期 #12）\n    网页版绝不碰玩家真实磁盘。四个动作（read / create / remove / revision）\n    全部落到一份**内存镜像**上，语义和桌面版 stmos 对齐：\n    remove 进虚拟回收站 `.trash/`，revision 先留一份 `.bak`。\n    IndexedDB 只有异步接口，Python 侧没法 await，所以持久化交给 JS：\n    每个事件之后页面调 `vfs_changes()` 把改动取走写进 IndexedDB；\n    启动时页面先读 IndexedDB，再 `load_vfs()` 灌回来。\n\"\"\"\n\nimport json\n\nfrom stmg import options as optmod\nfrom stmg import parser\nfrom stmg import stdlib_api\nfrom stmg import stmos\nfrom stmg.runtime import Runtime\n\n# R.api 的超时（毫秒），由页面上的 fetch 执行；契约要求 10 秒\nAPI_TIMEOUT_MS = 10000\n\n# 同一个请求最多交回给页面几次；页面一直不给结果就放弃，别把剧情卡死\nMAX_API_TRIES = 3\n\n# 联网失败时替换掉引擎那句干巴巴的「R.api 失败：None」\nAPI_FAIL_TEXT = (\"网页版联网没成功（超时 / 被跨域 CORS 挡住 / 断网），\"\n                 \"STM.API 是空的，剧情照常往下走\")\n\n# 沙箱文件系统用不了时的提示（只说一次）\nVFS_DOWN_TEXT = \"网页版沙箱文件系统用不了（浏览器不支持或你拒绝了），stm.os 已跳过\"\n\n\nclass _PendingAPI(BaseException):\n    \"\"\"R.api 在网页版里没法同步等：用它把「要发的请求」冒泡给 JS。\n\n    注意继承的是 **BaseException** 而不是 Exception —— runtime.run() 里有一层\n    `except Exception`（把引擎异常包成 fatal 事件），继承 Exception 会被它吞掉，\n    请求就永远送不到页面上了。\n    \"\"\"\n\n    def __init__(self, n, url, key):\n        BaseException.__init__(self)\n        self.n = n          # 这次请求在整份剧本里排第几（从 1 开始）\n        self.url = url\n        self.key = key\n\n\n# 当前正在跑的 Driver。Pyodide 是单线程、一次只跑一个剧本，所以用模块级变量\n# 把「被打了桩的 stdlib_api.call_api / stmos.*」接回实例。\n_ACTIVE = None\n\n\ndef _rel(path):\n    \"\"\"把引擎解析出来的虚拟路径还原成项目内的相对路径，前端好找素材。\"\"\"\n    p = str(path or \"\").replace(\"\\\\\", \"/\")\n    i = p.find(\"/game/\")\n    if i >= 0:\n        return p[i + 6:]\n    return p\n\n\n# --------------------------------------------------------------------------- #\n# 沙箱虚拟文件系统（Python 侧的内存镜像）\n# --------------------------------------------------------------------------- #\nclass VirtualFS(object):\n    \"\"\"stm.os 在浏览器里的「磁盘」。\n\n    这里只是一份内存镜像，真正的持久化在 JS 那边的 IndexedDB。\n    语义严格对齐桌面版 stmg/stmos.py：\n\n        read     读内容，读不到返回 (False, \"\")\n        create   建空文件，已存在就不动\n        remove   **移进虚拟回收站**，不是永久删除，能找回\n        revision 改内容前先留一份 `.bak`，改坏了能还原\n\n    另外：不管剧本里的路径写成 `C:/Users/xxx/a.txt` 还是\n    `stmg-virtual://save/a.txt`，都只是这份镜像里的一个键——\n    网页版碰不到真实磁盘，这是硬保证。\n    \"\"\"\n\n    TRASH = \".trash\"\n\n    SCHEME = \"stmg-virtual:\"\n\n    def __init__(self):\n        self.files = {}          # \"a/b/c.txt\" -> 内容\n        self.dirty = {}          # 还没有同步给 IndexedDB 的改动：路径 -> 新内容 / None=删除\n        self.enabled = True      # 浏览器不支持或用户拒绝时置 False，全体降级\n        self._warned = False\n        self._root = \"\"          # 引擎眼里的项目根目录，归一化时剥掉\n\n    def set_root(self, root):\n        \"\"\"记下引擎的项目根目录。\n\n        剧本里写相对路径时，runtime 会把它拼成 `<root>/notes/a.txt`；\n        写 `stmg-virtual://notes/a.txt` 时又不会拼。两种写法剥掉根目录后\n        指向同一个文件，玩家不用关心自己写的是哪一种。\n        \"\"\"\n        self._root = self._norm(str(root or \"\"), strip_root=False)\n\n    # -- 路径归一化 ------------------------------------------------------ #\n    def norm(self, path):\n        \"\"\"任何写法都归一成镜像里的键：去掉协议 / 盘符 / 项目根目录，折叠 `..`。\"\"\"\n        return self._norm(str(path or \"\"), strip_root=True)\n\n    def _norm(self, path, strip_root):\n        p = path.strip().replace(\"\\\\\", \"/\")\n        # `stmg-virtual://x` 可能出现被 resolve() 拼到根目录后面的形式\n        # （如 `/game/stmg-virtual://x`），所以按「第一次出现」切，不看开头\n        i = p.lower().find(self.SCHEME)\n        if i >= 0:\n            p = p[i + len(self.SCHEME):]\n        elif len(p) > 1 and p[1] == \":\":        # 吃掉 C: / D: 这样的盘符\n            p = p[2:]\n        parts = []\n        for seg in p.split(\"/\"):\n            seg = seg.strip()\n            if seg in (\"\", \".\"):\n                continue\n            if seg == \"..\":\n                if parts:\n                    parts.pop()\n                continue\n            parts.append(seg)\n        k = \"/\".join(parts)\n        if strip_root and self._root:\n            if k == self._root:\n                return \"\"\n            if k.startswith(self._root + \"/\"):\n                k = k[len(self._root) + 1:]\n        return k\n\n    def _set(self, key, content):\n        if content is None:\n            self.files.pop(key, None)\n        else:\n            self.files[key] = content\n        self.dirty[key] = content\n\n    # -- 降级 ------------------------------------------------------------ #\n    def degraded(self):\n        \"\"\"标记「用不了」，返回提示文案（只在第一次给文案）。\"\"\"\n        if self._warned:\n            return \"\"\n        self._warned = True\n        return VFS_DOWN_TEXT\n\n    # -- 四个动作（对齐桌面版 stmos 的返回值） ---------------------------- #\n    def read(self, path):\n        if not self.enabled:\n            return False, \"\"\n        k = self.norm(path)\n        if not k:\n            return False, \"\"\n        return (True, self.files[k]) if k in self.files else (False, \"\")\n\n    def create(self, path):\n        if not self.enabled:\n            return False, \"沙箱不可用\"\n        k = self.norm(path)\n        if not k:\n            return False, \"没给路径\"\n        if k in self.files:\n            return True, \"已存在，未改动\"\n        self._set(k, \"\")\n        return True, \"\"\n\n    def remove(self, path):\n        if not self.enabled:\n            return False, \"沙箱不可用\"\n        k = self.norm(path)\n        if not k:\n            return False, \"没给路径\"\n        if k not in self.files:\n            return True, \"不存在，跳过\"\n        # 桌面版走系统回收站；网页版走虚拟回收站，同样「误删能找回」\n        name = k.split(\"/\")[-1]\n        dest = \"%s/%s\" % (self.TRASH, name)\n        i = 1\n        while dest in self.files:\n            i += 1\n            dest = \"%s/%s.%d\" % (self.TRASH, name, i)\n        self._set(dest, self.files[k])\n        self._set(k, None)\n        return True, \"\"\n\n    def revision(self, path, old, new):\n        if not self.enabled:\n            return False, \"沙箱不可用\"\n        if old is None or new is None:\n            return False, \"revision 需要 ,\\\"旧内容\\\"to\\\"新内容\\\"\"\n        k = self.norm(path)\n        if not k:\n            return False, \"没给路径\"\n        if k not in self.files:\n            return False, \"文件不存在\"\n        self._set(k + \".bak\", self.files[k])          # 先备份，和桌面版一样\n        self._set(k, self.files[k].replace(old, new) if old else new)\n        return True, \"\"\n\n    # -- 和页面同步 ------------------------------------------------------ #\n    def take_changes(self):\n        \"\"\"把「还没落盘的改动」交给页面去写 IndexedDB；没改动返回 None。\"\"\"\n        if not self.dirty:\n            return None\n        add, drop = {}, []\n        for k, v in self.dirty.items():\n            if v is None:\n                drop.append(k)\n            else:\n                add[k] = v\n        self.dirty = {}\n        return {\"set\": add, \"del\": drop}\n\n\n# --------------------------------------------------------------------------- #\n# 给引擎打的桩\n# --------------------------------------------------------------------------- #\ndef _call_api(url=\"\", key=\"\", method=\"GET\", params=None, data=None):\n    \"\"\"stdlib_api.call_api 的网页版实现：不真发请求，交给页面去 fetch。\"\"\"\n    drv = _ACTIVE\n    if drv is None:\n        return False, \"网页版还没有引擎在跑，联网请求被跳过\"\n    return drv.ask_api(url, key)\n\n\ndef _web_read_file(path):\n    \"\"\"stmos.read_file 的网页版实现：没引擎在跑就返回空，否则读沙箱。\"\"\"\n    drv = _ACTIVE\n    if drv is None:\n        return False, \"\"\n    return drv.vfs.read(path)\n\n\ndef _web_create_file(path):\n    \"\"\"stmos.create_file 的网页版实现：转发到当前引擎的虚拟文件系统。\"\"\"\n    drv = _ACTIVE\n    if drv is None:\n        return False, \"网页版还没有引擎在跑\"\n    return drv.vfs.create(path)\n\n\ndef _web_remove_file(path):\n    \"\"\"stmos.remove_file 的网页版实现：转发到当前引擎的虚拟文件系统。\"\"\"\n    drv = _ACTIVE\n    if drv is None:\n        return False, \"网页版还没有引擎在跑\"\n    return drv.vfs.remove(path)\n\n\ndef _web_revision_file(path, old, new):\n    \"\"\"stmos.revision_file 的网页版实现：转发到当前引擎的虚拟文件系统。\"\"\"\n    drv = _ACTIVE\n    if drv is None:\n        return False, \"网页版还没有引擎在跑\"\n    return drv.vfs.revision(path, old, new)\n\n\nstdlib_api.call_api = _call_api\nstmos.read_file = _web_read_file\nstmos.create_file = _web_create_file\nstmos.remove_file = _web_remove_file\nstmos.revision_file = _web_revision_file\n\n\n# --------------------------------------------------------------------------- #\n# Driver\n# --------------------------------------------------------------------------- #\nclass Driver(object):\n    \"\"\"网页版对外的引擎驱动器：一次只跑一个剧本（Pyodide 单线程）。\n\n    用法：Driver(script_text, options_text) 建好之后，反复调 next(answer)\n    把事件一条条吐给页面；页面把 R.api 的结果用 resolve_api() 送回来、\n    把沙箱改动用 vfs_changes() 取走、启动时用 load_vfs() 灌回。\n    详见文件头说明的「① R.api 异步」「② stm.os 沙箱」。\n    \"\"\"\n    def __init__(self, script_text, options_text=\"\", script_path=\"/game/script.stm\"):\n        # script_path 只是个「引擎眼里的剧本路径」：Pyodide 里是 /game/script.stm\n        # （MEMFS 里的假路径，成就 / CG 这类小文件写在那儿，重启就没了）。\n        # 留成参数是为了让自测能指到临时目录，不去碰真实磁盘。\n        global _ACTIVE\n        self.script = parser.parse_text(script_text, script_path)\n        try:\n            self.opt = optmod.parse_options_text(options_text) if options_text else {}\n        except Exception:                              # noqa: BLE001\n            self.opt = {}\n        self.vfs = VirtualFS()\n        self.api_cache = {}          # 请求序号 -> (ok, result)\n        self.api_tries = {}          # 请求序号 -> 已交给页面几次\n        self.delivered = 0           # 已经发给页面的「引擎事件」条数（统计用）\n        self.asked = 0               # 其中有多少条是 choose / question\n        self.queue = []              # 下一拍要先吐出来的事件（降级提示用）\n        self.toast_once = \"\"         # 攒着的一条提示，插到下一个事件前面\n        self.skip_until_api = 0      # >0：正在补跑，直到撞上这个序号的请求为止\n        self.pending_n = 0           # 已经交给页面 fetch、还没等到结果的请求序号\n        self.done = False\n        self._reset()\n        _ACTIVE = self\n\n    # ------------------------------------------------------------------ #\n    # 执行流\n    # ------------------------------------------------------------------ #\n    def _reset(self):\n        \"\"\"从剧本开头重建执行流（第一次跑 / 补跑都用它）。\"\"\"\n        self.rt = Runtime(self.script, self.opt, dev_mode=False)\n        self.gen = self.rt.run()\n        self.vfs.set_root(self.rt.root)\n        self.delivered = 0\n        self.asked = 0\n        self.skip_until_api = 0\n        self.pending_n = 0\n\n    def _resume(self, n):\n        \"\"\"页面把第 n 个请求的结果送回来了 —— 重建执行流、接回挂起点。\n\n        为什么要重建：Python 侧没法 await 页面的 fetch，R.api 只能先把请求\n        冒泡出去，那个生成器已经死在异常里、接不回来了。所以换一个新的，\n        把之前记下的 `answers` 原样喂回去，它会走出和第一次完全一样的路。\n\n        怎么知道「已经跑完挂起点之前的那些」：`ask_api` 每次被叫到都会报出\n        自己是第几个请求，撞上 n 就说明前面都跑完了 —— 从那一刻起的事件\n        才是页面还没看过的。**用序号而不是事件条数**，是因为首轮和重放产出\n        的事件条数本来就不一样（见文件头说明），数条数会算错账。\n        \"\"\"\n        replay = list(self.rt.answers)\n        self.rt = Runtime(self.script, self.opt, dev_mode=False)\n        self.gen = self.rt.run(replay=replay)\n        self.vfs.set_root(self.rt.root)\n        self.skip_until_api = n\n        self.pending_n = 0\n\n    # ------------------------------------------------------------------ #\n    # R.api\n    # ------------------------------------------------------------------ #\n    def _api_ordinal(self):\n        \"\"\"这次 api 调用在整份剧本里排第几。\n\n        已经被回放短路掉的请求也会记在 `answers` 里，一起数进来，\n        这样重跑之后序号仍然对得上（缓存不会串位）。\n        \"\"\"\n        k = 0\n        for item in self.rt.answers:\n            if item and item[0] == \"api\":\n                k += 1\n        return k + 1\n\n    def ask_api(self, url, key):\n        \"\"\"引擎问「这个 URL 的结果是什么」。有缓存直接给，没有就挂起。\"\"\"\n        n = self._api_ordinal()\n        if self.skip_until_api and n >= self.skip_until_api:\n            # 补跑跑到挂起点了：从这里开始的事件页面都还没看过，别再丢了\n            self.skip_until_api = 0\n        if n in self.api_cache:\n            return self.api_cache[n]\n        raise _PendingAPI(n, str(url or \"\"), str(key or \"\"))\n\n    def _on_pending(self, p):\n        \"\"\"把挂起的请求变成一条事件交给页面，等它 fetch 完再叫我们。\"\"\"\n        n = p.n\n        tries = self.api_tries.get(n, 0) + 1\n        self.api_tries[n] = tries\n        if tries > MAX_API_TRIES:\n            # 页面一直没把结果送回来：直接当失败处理，别把剧情卡死\n            self.api_cache[n] = (False, None)\n            self._resume(n)\n            return self.next(None)\n        self.pending_n = n\n        return json.dumps({\"t\": \"api_pending\", \"n\": n, \"url\": p.url, \"key\": p.key,\n                           \"timeout\": API_TIMEOUT_MS, \"tries\": tries},\n                          ensure_ascii=False)\n\n    # ------------------------------------------------------------------ #\n    # 对外接口\n    # ------------------------------------------------------------------ #\n    def next(self, answer=None):\n        while True:\n            if self.queue:\n                return json.dumps(self.queue.pop(0), ensure_ascii=False)\n            if self.done:\n                return json.dumps({\"t\": \"__done__\"})\n            if self.pending_n:\n                # 有请求挂起过：新一轮进来就是重建执行流、接回挂起点。\n                # 页面还没把结果送回来的话，重跑会再挂起一次（tries 兜底）。\n                self._resume(self.pending_n)\n            try:\n                ev = self.gen.send(answer)\n            except StopIteration:\n                self.done = True\n                return json.dumps({\"t\": \"__done__\"})\n            except _PendingAPI as p:\n                return self._on_pending(p)\n            except BaseException as e:                      # noqa: BLE001\n                self.done = True\n                return json.dumps({\"t\": \"fatal\",\n                                   \"message\": \"%s: %s\" % (type(e).__name__, e)})\n            answer = None\n            out = self._emit(ev)\n            if out is None:\n                continue            # 补跑阶段：这条页面早看过了，丢掉\n            return out\n\n    def _emit(self, ev):\n        \"\"\"整理并交出一条事件；补跑阶段返回 None 表示「这条丢掉」。\"\"\"\n        if self.skip_until_api:\n            return None\n        ev = dict(ev)\n        if ev.get(\"path\"):\n            ev[\"path\"] = _rel(ev[\"path\"])\n        ev = self._polish(ev)\n        self.delivered += 1\n        if ev.get(\"t\") in (\"choose\", \"question\"):\n            self.asked += 1\n        self._sync_vfs_state()\n        if self.toast_once:\n            text, self.toast_once = self.toast_once, \"\"\n            self.queue.append(ev)               # 真事件挪到下一拍，别被提示顶掉\n            return json.dumps({\"t\": \"toast\", \"text\": text}, ensure_ascii=False)\n        return json.dumps(ev, ensure_ascii=False)\n\n    def _polish(self, ev):\n        \"\"\"把引擎吐出来的事件顺手修一下（只动文案，不动语义）。\"\"\"\n        if ev.get(\"t\") == \"toast\":\n            t = str(ev.get(\"text\") or \"\")\n            if t.startswith(\"R.api 失败\"):\n                ev[\"text\"] = API_FAIL_TEXT\n        return ev\n\n    def _queue_toast(self, text):\n        if text and not self.toast_once:\n            self.toast_once = text\n\n    def _sync_vfs_state(self):\n        \"\"\"沙箱被降级时，攒一句提示插到事件流里。\"\"\"\n        if not self.vfs.enabled and not self.vfs._warned:\n            self._queue_toast(self.vfs.degraded())\n\n    # -- 页面回调 -------------------------------------------------------- #\n    def resolve_api(self, n, ok, result=None):\n        \"\"\"页面 fetch 完之后把结果送回来。\"\"\"\n        try:\n            n = int(n)\n        except (TypeError, ValueError):\n            return json.dumps({\"ok\": False, \"why\": \"n 不是整数\"}, ensure_ascii=False)\n        if result is not None and not isinstance(result, str):\n            result = str(result)\n        self.api_cache[n] = (bool(ok), result)\n        return json.dumps({\"ok\": True, \"n\": n}, ensure_ascii=False)\n\n    def vfs_changes(self):\n        \"\"\"页面每拿到一条事件就调一次：把还没落盘的沙箱改动取走。\"\"\"\n        ch = self.vfs.take_changes()\n        return json.dumps(ch, ensure_ascii=False) if ch else \"null\"\n\n    def load_vfs(self, text):\n        \"\"\"页面读完 IndexedDB 之后，把沙箱文件灌回来。\"\"\"\n        try:\n            data = json.loads(text) if text else {}\n        except Exception:                               # noqa: BLE001\n            return json.dumps({\"ok\": False, \"n\": 0, \"why\": \"不是合法的 JSON\"},\n                              ensure_ascii=False)\n        if not isinstance(data, dict):\n            data = {}\n        n = 0\n        for k, v in data.items():\n            kk = self.vfs.norm(k)\n            if kk and isinstance(v, str):\n                self.vfs.files[kk] = v\n                n += 1\n        return json.dumps({\"ok\": True, \"n\": n}, ensure_ascii=False)\n\n    def set_vfs_enabled(self, flag):\n        \"\"\"页面告诉引擎沙箱能不能用；不能就全体降级成「跳过 + 提示」。\"\"\"\n        self.vfs.enabled = bool(flag)\n        if not self.vfs.enabled:\n            self._sync_vfs_state()\n        return json.dumps({\"ok\": True, \"enabled\": self.vfs.enabled},\n                          ensure_ascii=False)\n\n    # ------------------------------------------------------------------ #\n    def info(self):\n        \"\"\"给前端的一点点元信息。\"\"\"\n        return json.dumps({\"title\": self.script.title,\n                           \"w\": self.script.width, \"h\": self.script.height,\n                           \"ver\": self.script.header.get(\"ver\", \"1.0.0\"),\n                           \"errors\": self.script.error_count(),\n                           \"api_timeout\": API_TIMEOUT_MS},\n                          ensure_ascii=False)\n","/stmg_root/stmg/avg.py":"# -*- coding: utf-8 -*-\n\"\"\"STMG AVG 绘图系统（第 3 期新增）—— 剧本里的「画图/画形状」引擎核心。\n\n这个模块是整个 AVG 系统的**纯计算核心**：只负责「把绘图指令变成几何图形」，\n不依赖 pygame、不依赖浏览器——桌面版（pygame）和网页版（canvas）都 import\n同一份代码来算几何，保证两边画出来的东西一模一样。\n\n实际「把几何画到屏幕上」的代码在两处：\n    桌面版：stmg/render.py 的 draw_avg()（用 pygame 画）\n    网页版：stmg/webplayer.html 里的 applyAvg()/runTurtle()（用 canvas 画）\n    （网页版没法 import 这份 Python，所以 JS 里有一份逐行对齐的翻译版，\n      改这里的规则时务必同步改 webplayer.html 里的 runTurtle！）\n\n==========================================================================\n剧本语法（在 .stm 剧本里这样写）\n==========================================================================\n\n1) 坐标系\n    游戏画面有一个坐标系，(x:0, y:0) 是画面的**正中间**；\n    x 向右为正，y 向上为正（数学课本的习惯）。\n    例如 1280x720 的窗口：右下角大约是 (640, -360)。\n\n2) 放一个形状\n    S.AVG-button(x:100, y:50, \"box\")\n    S.AVG-button(-200, 0, \"circle\", color=\"#ff5577\", size=120)\n    S.AVG-button(0, 0, \"我的画\")          ← 「我的画」是下面 SET 定义的\n    - 前两个参数是坐标（写 x:/y: 或直接按顺序写都行）；\n    - 第三个参数是形状名：\n        \"box\"      方框（内置）\n        \"circle\"   圆圈（内置）\n        其他名字   必须是 SET 定义的绘图变量（见下），没定义就不画；\n    - 可选参数：\n        color=\"#rrggbb\"  线的颜色（默认白色）\n        size=数字         内置形状的大小：box 是边长、circle 是直径（默认 64）\n        width=数字        线宽（默认 3）\n\n3) 用 SET 定义自己的画（海龟绘图，和 LOGO 的小海龟一个思路）\n    SET 三角形:\n        go(100px)\n        left(120)\n        go(100px)\n        left(120)\n        go(100px)\n    然后就能 S.AVG-button(0, 0, \"三角形\") 把它画在画面正中。\n    一支看不见的「笔」从 (0,0) 出发、默认朝右、默认落笔（移动会画线）：\n        go(距离)      前进（距离可以带 px，如 go(10px)）\n        back(距离)    后退\n        left(角度)    左转（逆时针，单位度）\n        right(角度)   右转（顺时针）\n        up()          抬笔（之后移动不画线）\n        down()        落笔（恢复画线）\n    额外送的几支（超出用户清单的扩展，不写就不用）：\n        goto(x, y)    跳到指定点（落笔状态会拖出一条线）\n        color(\"#rrggbb\")  换颜色\n        width(数字)       换线宽\n        circle(半径)      在当前位置画一个圆\n\n4) 清屏\n    S.AVG-clear()   ← 把 AVG 画的所有东西全部擦掉\n\n==========================================================================\n内部数据格式（别的模块怎么消费这里的输出）\n==========================================================================\n\n* 绘图指令 ops：列表里的每一项是 [\"指令名\", 参数]，例如\n      [[\"go\", 100.0], [\"left\", 120.0], [\"up\"], [\"goto\", [10.0, 20.0]]]\n  纯 JSON，能直接塞进网页版的 <script> 里。\n\n* 几何结果 geometry：run_turtle() / item_geometry() 的返回值，\n      {\"strokes\": [{\"c\": 颜色, \"w\": 线宽, \"pts\": [x1,y1, x2,y2, ...]}, ...],\n       \"circles\": [{\"c\": 颜色, \"w\": 线宽, \"cx\": x, \"cy\": y, \"r\": 半径}, ...]}\n  坐标是**局部数学坐标**（y 向上、原点在 S.AVG-button 指定的落点）。\n  渲染层拿到后自己翻成屏幕坐标：\n      屏幕 x = 画面宽/2 + 局部 x\n      屏幕 y = 画面高/2 - 局部 y        ← 注意 y 要翻转！\n\"\"\"\n\nimport math\nimport re\n\n# ---------------------------------------------------------------------------\n# 常量\n# ---------------------------------------------------------------------------\n\n# 引擎内置的形状名。S.AVG-button 的第三个参数是这些名字时直接用内置几何，\n# 是别的名字时去 Runtime 的 avg_shapes 表里找 SET 定义的绘图指令。\nPRIMITIVES = (\"box\", \"circle\")\n\n# 用户什么都没配的时候用的默认值\nDEFAULT_COLOR = \"#ffffff\"     # 默认线色：白\nDEFAULT_SIZE = 64.0           # 默认形状大小（box 边长 / circle 直径），像素\nDEFAULT_WIDTH = 3             # 默认线宽，像素\n\n# 一行绘图指令长什么样：go(10px) / left(90) / up() / goto(3,4) ...\nOP_LINE_RE = re.compile(r\"^([A-Za-z_]\\w*)\\s*\\(\\s*(.*?)\\s*\\)\\s*$\")\n# 一个「数」长什么样：10 / -3.5 / 10px（px 后缀可选，大小写不限）\nNUM_RE = re.compile(r\"^(-?\\d+(?:\\.\\d+)?)(?:px)?$\", re.I)\n# 颜色长什么样：#abc 或 #aabbcc（别的不认，写错会报 Issue）\nCOLOR_RE = re.compile(r\"^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$\")\n\n# SET 绘图块里允许出现的指令名 -> 参数要求。\n#   \"num\"   一个数（可带 px）\n#   \"angle\" 一个数（度数，不允许 px，但解析上和 num 一样，兼容写法）\n#   \"none\"  括号里必须为空：up() / down()\n#   \"xy\"    两个数，逗号隔开：goto(10, 20)\n#   \"color\" 一个 #开头的颜色\n# 参数要求在解析期（parser.py）就检查，写错了直接在 check 阶段报出来，\n# 不会拖到玩家玩到一半才炸。\nOP_SPEC = {\n    \"go\": \"num\", \"back\": \"num\", \"left\": \"angle\", \"right\": \"angle\",\n    \"up\": \"none\", \"down\": \"none\",\n    \"goto\": \"xy\", \"color\": \"color\", \"width\": \"num\", \"circle\": \"num\",\n}\n\n\n# ---------------------------------------------------------------------------\n# 小工具：解析数字和颜色\n# ---------------------------------------------------------------------------\ndef parse_num(text, default=0.0):\n    \"\"\"把 \"10px\" / \"-3.5\" / \"10\" 解析成 float。\n\n    解析不出东西（空串、写成了 \"abc\"）时返回 default —— 绘图指令里写错\n    数字不该让整个游戏崩掉，退回默认值继续跑。\n    \"\"\"\n    m = NUM_RE.match(str(text or \"\").strip())\n    if not m:\n        return float(default)\n    return float(m.group(1))\n\n\ndef hex_to_rgb(color, default=(255, 255, 255)):\n    \"\"\"把 \"#ffffff\" / \"#fff\" 变成 pygame 要的 (r, g, b) 元组。\n\n    只有桌面版渲染（render.py 的 draw_avg）用得到——网页版的 canvas\n    直接吃 \"#ffffff\" 字符串，不用转。\n    认不出（空串、写错）返回 default，别让一个颜色写错弄崩渲染。\n    \"\"\"\n    s = str(color or \"\").strip()\n    m = COLOR_RE.match(s)\n    if not m:\n        return default\n    s = s[1:]                       # 去掉开头的 #\n    if len(s) == 3:                 # #abc -> #aabbcc，每位重复一次\n        s = \"\".join(ch * 2 for ch in s)\n    return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4))\n\n\n# ---------------------------------------------------------------------------\n# 解析期：把 SET 块里的一行指令编译成 ops 列表的一项\n# ---------------------------------------------------------------------------\ndef compile_op_line(raw):\n    \"\"\"把 SET 绘图块里的一行（如 \"go(10px)\"）编译成一条指令。\n\n    返回 (指令, 错误信息)：\n        成功 -> ([\"go\", 10.0], None)\n        失败 -> (None, \"人话错误说明\")   ← parser 拿它去报 Issue\n    指令统一是 [名字, 参数] 的列表（纯 JSON），参数可能是：\n        数字（go/back/left/right/width/circle）\n        数字对 [x, y]（goto）\n        颜色字符串（color）\n        什么都不带（up/down，只有一项）\n    \"\"\"\n    s = str(raw or \"\").strip()\n    if not s:\n        return None, None            # 空行直接跳过，不算错\n    m = OP_LINE_RE.match(s)\n    if not m:\n        return None, \"看不懂的绘图指令：%s（应该写成 go(10px) / left(90) 这样的）\" % s[:30]\n    name = m.group(1).lower()        # GO(10px) 和 go(10px) 等价\n    arg = m.group(2).strip()\n    spec = OP_SPEC.get(name)\n    if spec is None:\n        return None, \"没有「%s」这条绘图指令（有：%s）\" % (\n            name, \"、\".join(sorted(OP_SPEC)))\n\n    if spec == \"none\":\n        # up() / down()：括号里不该有东西；有就提醒（宽容处理，照常执行）\n        if arg:\n            return None, \"%s() 括号里不该写东西，写成 %s() 就行\" % (name, name)\n        return [name], None\n\n    if spec == \"num\" or spec == \"angle\":\n        if not NUM_RE.match(arg):\n            return None, \"%s 的参数应该是一个数（可带 px），这里写的是：%s\" % (name, arg[:20])\n        return [name, float(NUM_RE.match(arg).group(1))], None\n\n    if spec == \"xy\":\n        parts = [p.strip() for p in arg.split(\",\") if p.strip()]\n        if len(parts) != 2 or not all(NUM_RE.match(p) for p in parts):\n            return None, \"%s 的参数应该是两个数，逗号隔开（如 %s(10, 20)）\" % (name, name)\n        return [name, [float(NUM_RE.match(p).group(1)) for p in parts]], None\n\n    if spec == \"color\":\n        c = arg.strip().strip('\"')   # 允许写成 color(\"#ff0000\")，引号剥掉\n        if not COLOR_RE.match(c):\n            return None, \"颜色要写成 #rgb 或 #rrggbb（如 #ff5577），这里写的是：%s\" % c[:20]\n        return [name, c.lower()], None\n\n    return None, None                # 理论上走不到（spec 表写错了才会）\n\n\ndef compile_ops(lines):\n    \"\"\"把 SET 绘图块的全部行编译成 ops 列表。\n\n    返回 (ops, issues)：issues 是 [(行文本, 错误信息), ...]，\n    parser 拿它去生成带行号的 Issue。有错的行**跳过不收**，\n    这样一处小笔误不至于让整幅画废掉。\n    \"\"\"\n    ops, issues = [], []\n    for ln in lines:\n        op, err = compile_op_line(ln)\n        if err:\n            issues.append((ln, err))\n        elif op is not None:\n            ops.append(op)\n    return ops, issues\n\n\n# ---------------------------------------------------------------------------\n# 运行期：把绘图指令跑一遍，得到几何图形\n# ---------------------------------------------------------------------------\ndef run_turtle(ops, color=DEFAULT_COLOR, width=DEFAULT_WIDTH):\n    \"\"\"执行海龟绘图指令，返回几何结果（格式见文件头注释）。\n\n    一支看不见的笔：\n        位置 (x, y) 从 (0, 0) 出发 —— 就是 S.AVG-button 指定的落点；\n        朝向 head，0 度 = 朝右（+x），逆时针为正（和数学课一致）；\n        笔状态 pen，True = 落笔（移动会画线），默认就是落笔。\n    坐标系是 y 向上的数学坐标，**翻成屏幕坐标是渲染层的活**，这里不管。\n\n    ops 里每条是 [名字, 参数]；不带参数的（up/down）就是 [名字]。\n    遇到看不懂的指令直接跳过（解析期已经拦过一遍，这里是双保险，\n    比如老存档重放时喂进来的旧数据）。\n    \"\"\"\n    x = y = 0.0\n    head = 0.0\n    pen = True\n    cur_color = str(color or DEFAULT_COLOR)\n    cur_width = int(width or DEFAULT_WIDTH)\n\n    strokes = []          # 结果：一串折线\n    circles = []          # 结果：一串圆\n    cur = None            # 当前正在画的折线（换色/换线宽/抬笔时会断开）\n\n    def start_stroke(px, py):\n        \"\"\"开一段新折线（当前颜色/线宽）。\"\"\"\n        return {\"c\": cur_color, \"w\": cur_width, \"pts\": [px, py]}\n\n    def line_to(nx, ny):\n        \"\"\"从当前位置画线到 (nx, ny)——落笔才真画，抬笔就只挪位置。\"\"\"\n        nonlocal x, y, cur\n        if pen:\n            if cur is None:\n                cur = start_stroke(x, y)\n                strokes.append(cur)\n            cur[\"pts\"].extend([nx, ny])\n        else:\n            cur = None     # 抬笔移动：下一次落笔要另起一段\n        x, y = nx, ny\n\n    for op in ops or []:\n        name = str(op[0]).lower() if op else \"\"\n        arg = op[1] if len(op) > 1 else None\n\n        if name == \"go\" or name == \"back\":\n            # 前进/后退：沿当前朝向移动 arg 像素（back 就是负方向）\n            d = float(arg or 0.0)\n            if name == \"back\":\n                d = -d\n            # 三角函数算落点：head=0 朝右，90 度朝上（数学坐标 y 向上）\n            import math\n            rad = math.radians(head)\n            line_to(x + d * math.cos(rad), y + d * math.sin(rad))\n\n        elif name == \"left\":\n            head += float(arg or 0.0)      # 左转 = 逆时针 = 角度加\n        elif name == \"right\":\n            head -= float(arg or 0.0)      # 右转 = 顺时针 = 角度减\n\n        elif name == \"goto\":\n            gx, gy = (arg or [0.0, 0.0])[0:2]\n            line_to(float(gx), float(gy))\n\n        elif name == \"up\":\n            pen = False\n            cur = None                     # 抬笔断开当前折线\n        elif name == \"down\":\n            pen = True\n\n        elif name == \"color\":\n            cur_color = str(arg or DEFAULT_COLOR)\n            cur = None                     # 换色另起一段，免得一条折线两种色\n        elif name == \"width\":\n            cur_width = max(1, int(float(arg or DEFAULT_WIDTH)))\n            cur = None\n        elif name == \"circle\":\n            # 在笔的当前位置画一个圆（不影响笔的位置和朝向）\n            circles.append({\"c\": cur_color, \"w\": cur_width,\n                            \"cx\": x, \"cy\": y, \"r\": abs(float(arg or 10.0))})\n\n        # 其他名字：跳过（见函数开头的说明）\n\n    return {\"strokes\": strokes, \"circles\": circles}\n\n\ndef primitive_geometry(name, size=DEFAULT_SIZE, color=DEFAULT_COLOR,\n                       width=DEFAULT_WIDTH):\n    \"\"\"内置形状（box / circle）的几何。\n\n    box    以落点为中心的正方形，边长 size；\n    circle 以落点为圆心的圆，直径 size（半径 size/2）。\n    不是内置形状返回 None，调用方改走 run_turtle()。\n    \"\"\"\n    name = str(name or \"\").lower()\n    s = float(size or DEFAULT_SIZE)\n    if name == \"box\":\n        h = s / 2.0\n        # 五个点首尾相接画成一个闭合方框\n        pts = [-h, -h, h, -h, h, h, -h, h, -h, -h]\n        return {\"strokes\": [{\"c\": color, \"w\": int(width or DEFAULT_WIDTH),\n                             \"pts\": pts}], \"circles\": []}\n    if name == \"circle\":\n        return {\"strokes\": [],\n                \"circles\": [{\"c\": color, \"w\": int(width or DEFAULT_WIDTH),\n                             \"cx\": 0.0, \"cy\": 0.0, \"r\": s / 2.0}]}\n    return None\n\n\ndef item_geometry(item):\n    \"\"\"一条 AVG 场景物品（S.AVG-button 事件存进 scene[\"avg\"] 的 dict）\n    -> 几何结果。桌面渲染（render.py）和网页渲染（webplayer.html 的 JS\n    翻译版）都按这个语义画。\n\n    item 里可能有：shape（形状名）/ ops（用户绘图的指令）/ x, y（落点，\n    这里不用——平移是渲染层的事）/ color / size / width（一次性覆盖默认值）。\n    \"\"\"\n    name = str(item.get(\"shape\") or \"\").lower()\n    color = str(item.get(\"color\") or DEFAULT_COLOR)\n    width = item.get(\"width\")\n    size = item.get(\"size\")\n\n    # 先试内置形状\n    geo = primitive_geometry(name, size if size is not None else DEFAULT_SIZE,\n                             color, width if width is not None else DEFAULT_WIDTH)\n    if geo is not None:\n        return geo\n\n    # 不是内置形状：按用户 SET 定义的指令跑一遍。\n    # item[\"ops\"] 是 Runtime 在发事件时塞进来的（见 runtime.do_call），\n    # 空的说明形状没定义过——返回空几何，什么都不画，也不报错。\n    return run_turtle(item.get(\"ops\") or [],\n                      color=color,\n                      width=width if width is not None else DEFAULT_WIDTH)\n","/stmg_root/stmg/webtools.py":"# -*- coding: utf-8 -*-\n\"\"\"网页制作器（webmaker/）的后端工具：检查 / 素材扫描 / AST 导出。\n\n制作器在浏览器里通过 Pyodide 调这里的函数，拿到的全是 JSON 字符串，\n页面直接 JSON.parse。为什么另开一份而不复用 tools/check.py：那个是命令行\n工具，打印的是给人看的中文报告；制作器要的是**带行号的结构化数据**，\n用来在编辑器里画红点、在问题面板里点一下跳过去。语法判定仍然共用\nstmg.parser —— 网页说没毛病、命令行说有毛病这种事不会发生。\n\n对外四个函数：\n\n    check(script_text, options_text, asset_paths)\n        解析剧本，返回标题 / 分辨率 / 错误列表 / 统计 / 素材引用是否缺失\n    ast(script_text)\n        返回给页面内置解释器（--engine js）用的语句树\n    options_meta(options_text)\n        解析 options.stm，返回字段 + 它自己的 issue\n    version()\n        引擎版本号，制作器状态栏上显示用\n\"\"\"\n\nimport json\nimport os\nimport re\n\nfrom stmg import options as optmod\nfrom stmg import parser\nfrom stmg.errors import level_name\n\n# 和 htmlpub.py 里的两份扩展名表保持一致：网页版认得的素材类型\nIMG_EXTS = {\".png\", \".jpg\", \".jpeg\", \".webp\", \".bmp\", \".gif\", \".avif\"}\nAUD_EXTS = {\".ogg\", \".mp3\", \".wav\", \".opus\", \".m4a\", \".flac\", \".aac\"}\n\n# 会被当作「素材调用」的 S.* 方法（与 tools/doctor.py 的 ASSET_METHODS 同步）\nASSET_METHODS = (\"cg\", \"bg\", \"background\", \"picture\",\n                 \"character\", \"play\", \"sound\", \"voice\")\n\n_CALL_RE = re.compile(\n    r'\\bS\\.(cg|bg|background|picture|character|play|sound|voice)\\s*\\(', re.I)\n\n# 剧本里出现这些就算「动态路径」，静态判不了缺失，只提示不报错\n_DYN_MARKS = (\"+\", \"(\", \"STM\", \"R.\", \"[\")\n\n\ndef _looks_like_file(path):\n    \"\"\"S.character(\"角色1\") 里的「角色1」是注册名字，不是文件。\n\n    判据和 doctor.py 一样：带路径分隔符就算文件；否则看扩展名。\n    \"\"\"\n    p = path.replace(\"\\\\\", \"/\")\n    if \"/\" in p:\n        return True\n    return os.path.splitext(p)[1].lower() in (IMG_EXTS | AUD_EXTS)\n\n\ndef _match_paren(text, i):\n    \"\"\"从 i（指向左括号）找配对的右括号，只数圆括号。\n\n    STMG 的 {ruby:..} / [color:..] 是排版标记，混进来会把配对算错。\n    \"\"\"\n    depth = 0\n    while i < len(text):\n        c = text[i]\n        if c == \"(\":\n            depth += 1\n        elif c == \")\":\n            depth -= 1\n            if depth == 0:\n                return i\n        i += 1\n    return len(text)\n\n\ndef scan_refs(text):\n    \"\"\"扫出剧本引用的素材：[(方法, 路径, 是否动态)]。\n\n    这是 tools/doctor.py 里同一段逻辑的副本。复制而不是 import，是因为\n    tools/ 不在网页版的模块清单里（那边只装 stmg/*.py），\n    为了一个正则把整个 doctor.py 塞进 wasm 不划算。\n    \"\"\"\n    out = []\n    for m in _CALL_RE.finditer(text or \"\"):\n        method = m.group(1).lower()\n        j = _match_paren(text, m.end() - 1)\n        args = text[m.end():j]\n        sm = re.search(r'([\"\\'])(.*?)\\1', args, re.S)\n        if not sm:\n            continue\n        path = sm.group(2)\n        if not path or not _looks_like_file(path):\n            continue\n        dynamic = any(k in args for k in _DYN_MARKS)\n        out.append((method, path.replace(\"\\\\\", \"/\"), dynamic))\n    return out\n\n\ndef _count_nodes(node, acc):\n    \"\"\"递归数语句树：台词 / 选择 / 引擎调用 / python 块。\"\"\"\n    if isinstance(node, dict):\n        if \"k\" in node:\n            k = node.get(\"k\")\n            acc[\"nodes\"] += 1\n            if k == \"say\":\n                acc[\"say\"] += 1\n            elif k == \"choose\":\n                acc[\"choose\"] += 1\n            elif k == \"call\":\n                acc[\"call\"] += 1\n            elif k in (\"py_block\", \"python\"):\n                acc[\"python\"] += 1\n        for v in node.values():\n            _count_nodes(v, acc)\n    elif isinstance(node, list):\n        for v in node:\n            _count_nodes(v, acc)\n\n\ndef _issue_dict(it):\n    return {\"line\": int(getattr(it, \"line\", 0) or 0),\n            \"level\": str(getattr(it, \"level\", \"error\") or \"error\"),\n            \"message\": str(getattr(it, \"message\", \"\") or \"\"),\n            \"hint\": str(getattr(it, \"hint\", \"\") or \"\")}\n\n\ndef check(script_text, options_text=\"\", asset_paths=\"[]\"):\n    \"\"\"解析剧本并返回制作器要的全部信息（一次调用塞满，省得反复过桥）。\n\n    参数：\n      script_text   剧本文本（script.stm 原文）\n      options_text  options.stm 原文，可以空\n      asset_paths   页面已知的素材相对路径，JSON 数组字符串；用来判缺失\n\n    返回 JSON 字符串，键：\n      ok / title / w / h / font / ver / lines\n      issues        语法问题（带行号，error 和 warn 都在）\n      errors        其中 error 的条数\n      level         error 条数对应的级别叫法（A error / An error / Bro....）\n      stats         台词 / 选择 / 调用 / python 块 / 语句总数\n      refs          引用的素材：[{m,path,dynamic,found}]\n      missing       被引用但页面里没有的静态素材\n      unused        页面里有、但剧本没引用的素材\n      options       options.stm 解析结果 + 它自己的 issues\n\n    任何解析器抛异常都兜住返回 ok=false —— 制作器不能因为一份格式炸裂的\n    剧本整个卡死，玩家还要继续改。\n    \"\"\"\n    try:\n        sc = parser.parse_text(script_text or \"\", \"/game/script.stm\")\n    except BaseException as e:                              # noqa: BLE001\n        return json.dumps({\"ok\": False, \"fatal\": \"%s: %s\" % (type(e).__name__, e),\n                           \"issues\": [], \"errors\": 1, \"level\": \"A error\",\n                           \"title\": \"\", \"w\": 1280, \"h\": 720, \"font\": \"\",\n                           \"ver\": \"\", \"lines\": 0, \"stats\": {},\n                           \"refs\": [], \"missing\": [], \"unused\": [],\n                           \"options\": {}}, ensure_ascii=False)\n\n    acc = {\"say\": 0, \"choose\": 0, \"call\": 0, \"python\": 0, \"nodes\": 0}\n    try:\n        _count_nodes(getattr(sc, \"body\", None), acc)\n        _count_nodes(getattr(sc, \"ending\", None), acc)\n    except BaseException:                                   # noqa: BLE001\n        pass\n\n    issues = [_issue_dict(i) for i in getattr(sc, \"issues\", [])]\n    errors = len([i for i in issues if i[\"level\"] == \"error\"])\n\n    # ---- 素材 ----\n    try:\n        have = set(json.loads(asset_paths or \"[]\"))\n    except BaseException:                                   # noqa: BLE001\n        have = set()\n    have = set(str(x).replace(\"\\\\\", \"/\").lstrip(\"/\") for x in have)\n\n    refs, missing, seen = [], [], set()\n    for method, path, dynamic in scan_refs(script_text):\n        rel = path.lstrip(\"./\").lstrip(\"/\")\n        found = rel in have\n        refs.append({\"m\": method, \"path\": rel, \"dynamic\": bool(dynamic),\n                     \"found\": bool(found)})\n        if not dynamic:\n            seen.add(rel)\n            if not found and rel not in missing:\n                missing.append(rel)\n\n    unused = sorted(p for p in have\n                    if p and p not in seen\n                    and os.path.splitext(p)[1].lower() in (IMG_EXTS | AUD_EXTS))\n\n    # ---- options.stm ----\n    options, opt_issues = {}, []\n    if options_text:\n        try:\n            options = optmod.parse_options_text(options_text)\n            # parse_options_text 有可能把 issue 挂在返回的 dict 特殊键上，\n            # 这里只取普通字段，顺便把非字符串的值转成字符串给页面显示\n            options = {str(k): v for k, v in dict(options or {}).items()}\n        except BaseException as e:                          # noqa: BLE001\n            opt_issues.append({\"line\": 0, \"level\": \"error\",\n                               \"message\": \"options.stm 解析失败：%s\" % e,\n                               \"hint\": \"\"})\n    if options_text and \"Enc\" not in options and \"enc\" not in options:\n        opt_issues.append({\"line\": 0, \"level\": \"warn\",\n                           \"message\": \"options.stm 里没写 Enc，发布加密包时用不了\",\n                           \"hint\": '加上 Enc = \"你的口令\"'})\n\n    return json.dumps({\n        \"ok\": errors == 0,\n        \"title\": str(getattr(sc, \"title\", \"\") or \"\"),\n        \"w\": int(getattr(sc, \"width\", 1280) or 1280),\n        \"h\": int(getattr(sc, \"height\", 720) or 720),\n        \"font\": str(getattr(sc, \"font\", \"\") or \"\"),\n        \"ver\": str(sc.header.get(\"ver\", \"\") if hasattr(sc, \"header\") else \"\"),\n        \"lines\": (script_text or \"\").count(\"\\n\") + 1,\n        \"issues\": issues,\n        \"errors\": errors,\n        \"level\": level_name(errors) or \"\",\n        \"stats\": acc,\n        \"refs\": refs,\n        \"missing\": missing,\n        \"unused\": unused,\n        \"options\": {\"fields\": options, \"issues\": opt_issues},\n    }, ensure_ascii=False)\n\n\ndef ast(script_text):\n    \"\"\"返回 --engine js 用的语句树（导出单文件播放器时塞进 HTML）。\n\n    解析失败返回 \"null\"，导出的播放器会退回 wasm 引擎，不会白屏。\n    \"\"\"\n    try:\n        sc = parser.parse_text(script_text or \"\", \"/game/script.stm\")\n        data = {\"title\": sc.title,\n                \"ver\": sc.header.get(\"ver\", \"1.0.0\"),\n                \"w\": sc.width, \"h\": sc.height,\n                \"body\": sc.body, \"ending\": sc.ending}\n        return json.dumps(data, ensure_ascii=False)\n    except BaseException:                                   # noqa: BLE001\n        return \"null\"\n\n\ndef options_meta(options_text):\n    \"\"\"单独解析 options.stm（制作器的设置面板用）。\"\"\"\n    try:\n        d = dict(optmod.parse_options_text(options_text or \"\") or {})\n        return json.dumps({\"ok\": True, \"fields\": {str(k): v for k, v in d.items()}},\n                          ensure_ascii=False)\n    except BaseException as e:                              # noqa: BLE001\n        return json.dumps({\"ok\": False, \"why\": str(e), \"fields\": {}},\n                          ensure_ascii=False)\n\n\ndef version():\n    \"\"\"引擎版本（状态栏显示）。\"\"\"\n    return json.dumps({\"ok\": True, \"version\": \"maker-1.0\",\n                       \"python\": True}, ensure_ascii=False)\n"};
